// 取得某道 T2 题的主题大类
function getT2Theme(q){
  if(!q) return '其他';
  var k = String(q.id||'').replace(/-\d+$/,'');
  var img;
  if(typeof q.photo==='string') img = q.photo.split('/').pop().replace('.jpg','');
  else if(typeof q.photo==='number') img = 'sprite'+q.photo;
  else img = (typeof T2_PHOTO_MAP!=='undefined' && T2_PHOTO_MAP[k]) ? T2_PHOTO_MAP[k].split('/').pop().replace('.jpg','') : '';
  return T2_THEME_MAP[img] || '其他';
}
// 列出当前 Tarea 的所有主题（按出现顺序）
function listT2Themes(){
  var b = getSieleOralBank()[2] || [];
  var order = [], seen = {};
  b.forEach(function(q){ var t = getT2Theme(q); if(!seen[t]){ seen[t]=1; order.push(t); } });
  return order;
}
// 跳到某主题的第一题
function jumpT2Theme(theme){
  var b = getSieleOralBank()[2] || [];
  var i = b.findIndex(function(q){ return getT2Theme(q)===theme; });
  if(i>=0){ _sieleOralIdx = i; _sieleOralShown = false; stopSieleOral(true); toast('已跳到主题：'+theme); if(typeof _sieleSyncProgress==='function')_sieleSyncProgress(); save(); renderMain(); }
}
// 将真题回忆场景注入 SIELE_ORAL_BANK[2]（去重，现有24题不受影响）
SIELE_T2_EXAM.forEach(function(r){
  var id = r[0];
  var exists = SIELE_ORAL_BANK[2].some(function(q){return q.id===id;});
  if(exists)return;
  var cat = id.replace(/-\d+$/,'');
  var catPhoto = T2_PHOTO_MAP[cat] || null;
  var s = {id:id, sec:120, title:r[1], photo:catPhoto, keys:['personas','primer plano','al fondo','parece','posible'], q:'Describa la fotografía de forma organizada: presente la situación, localice a las personas, explique sus acciones, haga una hipótesis prudente y cierre con una idea general.', sourceType:'real-exam', sourceDoc:r[12], hintCn:r[13], overview:r[2], place:r[3], mood:r[4], foreground:r[5], object:r[6], background:r[7], relationship:r[8], inference:r[9], conclusión:r[10]};
  s.model = makeT2Model(s);
  SIELE_ORAL_BANK[2].push(s);
});

// ===== S3: 统一为 T2 题回填图片（修复 SIELE_T2_RECALL 注入时 photo 恒为 null 的问题）=====
// 依据 T2_PHOTO_MAP：按 id 去掉数字后缀查表；已有 photo 的题不覆盖
SIELE_ORAL_BANK[2].forEach(function(q){
  if(q.photo !== null && q.photo !== undefined) return;
  var k = String(q.id||'').replace(/-\d+$/,'');
  if(T2_PHOTO_MAP[k]) q.photo = T2_PHOTO_MAP[k];
});

const SIELE_T3_EXTRA = [
  ['decline-dog','拒绝帮朋友遛狗','Rechace la petición de un amigo para sacar a pasear a su perro.','perro,alergia,ocupada,prima,disculpa','Hola, Laura. ¿Qué tal? Hace mucho tiempo sin verte. He recibido tu mensaje. En cuanto a tu petición, me gustaría ayudarte, pero ojalá no pueda hacerlo. Es que mi mamá es alérgica a los pelos de animales. Por eso, es imposible que me permita llevar un perro a casa. Además, últimamente estoy muy ocupada por los exámenes que vienen. Lo siento mucho por no poder ayudarte. Pero no te preocupes, creo que mi prima María será la mejor candidata. Ella y toda su familia son amantes de perros. También tiene un perrito en su casa. Voy a llamarle y estoy segura de que podrá darte un favor. Al recibir su respuesta, voy a enviarte mensaje inmediatamente. ¡Hasta luego! Que tengas un buen día. Te pido disculpa por molestarte con esto, y recuerda: si tu prima tiene alergia a los animales, dímelo ahora para buscar otra solución.'],
  ['cena','邀请国外朋友来家里吃饭','Invite a un amigo extranjero a cenar en casa y presente la comida y la ocasión.','cenar,invitar,platos,cultura,fecha','Buenos días, Luisa, soy Juana. ¿Qué tal es tu vida? Hace mucho tiempo que no nos vemos y te echo mucho de menos. Te llamo por teléfono para invitarte a cenar en mi casa. Pues la semana que viene será mi cumpleaños y tengo intención de celebrar una fiesta, invitando a todos mis amigos y familiares. Además, en ese día, mi madre preparará varios platos típicos y locales de China. Es una cocinera muy famosa de nuestro barrio, de los que te he referido muchas veces. Entonces, puedes experimentar la fiesta con características chinas y disfrutarte de la comida típica de nuestro país. ¿Suena emocionante, verdad? El cumpleaños será el jueves de la semana que viene. Me gustaría quedar contigo a las dos y media de la tarde. De todas formas, si tienes dudas o simplemente no tienes tiempo para venir a mi casa, llámame por teléfono. Espero tu respuesta, un abrazo, hasta luego. Además, quiero que pruebes platos típicos de mi cultura, así que dime qué fecha te viene mejor.'],
  ['boda','邀请国外的亲戚参加婚礼','Invite a un familiar que vive en el extranjero a su boda y dé los detalles.','boda,invitar,fecha,lugar,esperar','Hola, Manuel. Hace casi 2 años que no nos vemos. ¿Qué tal es tu vida en el extranjero? La verdad es que te echo mucho de menos. Te llamo por teléfono para invitarte a mi boda. Bueno, estoy emocionada y porque será el día más importante de mi vida. A ver, el novio es mi colega que me ayudó mucho cuando recién entré en la empresa. Y a medida que nos conectamos, nos comunicamos, y nos conocemos más profundamente, nos enamoramos. Se llama Alonso, muy guapo y tiene ojos azules. Lo más importante es que me escucha y me respeta. En cuanto a la ceremonia, la celebraremos el día 7 de enero, a las dos de la tarde, en el hotel Wanda. Vamos a organizar una serie de actividades y serán muy divertidas. En fin, tengo muchas ganas de verte en mi boda y si tienes cualquier problema, no dudes en ponerte en contacto conmigo. Un abrazo muy cariñoso, quedo esperando tu respuesta y dales un recuerdo a mis tíos de mi parte. Hasta luego. En cuanto se conozca la fecha exacta y el lugar de la ceremonia, te aviso; solo me queda esperar verte allí.'],
  ['cine','拒绝和朋友看一部已经看过的电影，并推荐另一部','Rechace ver una película que ya conoce y recomiende otra, con hora y lugar.','película,recomendar,porque,quedar,confirmar','Hola, Juan. Hace mucho tiempo que no nos vemos. He recibido tu invitación a ir al cine para ver una película horrible. Es una buena idea y quiero quedarme contigo. Pero, creo que es mejor cambiar la película que vamos a ver. Ya que en realidad, he visto esta peli antes. De verdad, no me impresionó mucho, incluso un poco aburrido. Últimamente, María me ha aconsejado otra película de suspense recién estrenada. Dijo que fue la mejor peli de este año. ¿Qué te parece ver esta peli nueva? Si le conviene, ojalá podamos quedarnos a la puerta del cine al lado de nuestra universidad, a las 6 de la tarde este domingo. Espero a tu llamada para confirmar la hora. Chao. Voy a recomendarla porque tiene muy buenas críticas y, además, es corta.'],
  ['decline-shopping','拒绝朋友的逛街邀约，再另约时间','Rechace una invitación de compras y proponga otro día.','padre,médico,esperar,disculpa,martes','Hola, perdona. ¿Qué tal? He recibido tu invitación a ir de compras este fin de semana. Tengo muchas ganas de salirme contigo, pero ojalá no pueda hacerlo. Es que mi padre tiene una cita con el médico a la una y voy a acompañarle, podría intentar llegar a las dos y media para comer, pero es que no sé cuánto tiempo vamos a estar en el médico. A veces hay que esperar mucho y no puedo saber a qué hora vamos a terminar. ¿Qué te parece si quedamos para el otro día? ¿Te viene bien el martes por ejemplo? Podríamos ir al centro comercial que está al lado de tu oficina, y así no tiene que ir muy lejos. Espero a tu respuesta. Disculpa una vez más, un abrazo.'],
  ['turismo','提供你现居住地的旅游建议','Dé consejos a un amigo que visitará su ciudad: lugares, actividades y gastronomía.','ciudad,visitar,recomiendo,gastronomía,si','Buenos días, Laura. ¡Cuánto tiempo que no nos vemos! Me he enterado de que va a viajar a Qingdao la semana que viene. ¡Qué bien! En este sentido, puedo verte pronto. En cuanto a esta ciudad, creo que es muy apta para visitar. Es una ciudad antigua, con historia muy profunda, por eso, hay un montón de monumentos históricos. También es caracterizada por el mar limpio y la playa acogedora. Es una buena opción pasearse por el parque al lado del mar y hacer picnic en la playa por la tarde. Hablando de la gastronomía local, lo más importante es el marisco y la cerveza de Qingdao. Tienes que aprobarlas. Si tienes algún problema en el viaje, llámame a cualquier momento. Espero a tu llegada. Nos vemos en Qingdao. Para comer, te recomiendo el barrio antiguo, cerca de la catedral.'],
  ['vuelo','改签机票，说明原因、改签日期，解释为什么不需额外付费','Solicite cambiar la fecha de un vuelo, explique el motivo y mencione el seguro.','billete,cambiar,fecha,seguro,motivo','Buenos días. Mi nombre es Juan. El motivo por el que les llamo a ustedes es el siguiente: Hace dos meses compré un billete de avión para viajar de Madrid a Barcelona, a fin de tomar las vacaciones de verano con toda mi familia. Sin embargo, esta semana en mi ciudad la situación de pandemia se ha agravado. Según las políticas nuevas, todos los ciudadanos no pueden salir de la ciudad. Por eso, tengo que prorrogar el viaje a 1 de octubre, 3 meses después. El número de mi vuelo es MU276 y me gustaría cambiar la fecha del billete que reservé. Recuerdo que a la hora de comprar el billete también compré un seguro de viaje por si surgiera algún imprevisto y por lo tanto deduzco que no tendré que desembolsar otra vez por el cambio de fecha. Muchas gracias por atenderme y quedo esperando su respuesta, hasta luego.'],
  ['trabajo','更改/取消 就诊/上课/采访/餐厅预定的时间','Llame para cambiar o cancelar la hora de una cita (médica, clase, entrevista o restaurante).','cita,hora,disculpa,problema,confirmar','Buenas tardes, soy Antonio Pérez. Llamaba porque tenía una cita a las cinco de la tarde y no voy a poder ir. Es que tengo que ir a coger a mi hijo en el colegio, porque parece que no se encuentra bien y no me da tiempo las dos cosas. Lo siento mucho. Sé que es un poco tarde para avisar, pero es que me han llamado ahora. Les ruego que disculpen las molestias que les puedo causar. Si pueden, me gustaría pasar la cita a la semana que viene. Por ejemplo, el viernes por la mañana, a las nueve y media. Si le resulta inconveniente, podemos quedar cuando pueda. Espero su llamada para confirmar el día y la hora. Disculpe una vez más y muchas gracias. Si el cambio supone algún problema para ti, dímelo y buscamos otra fecha; de nuevo, mi disculpa por las molestias.'],
  ['enfermo','问候生病的朋友，并推迟约会','Pregunte por la salud de un amigo y proponga aplazar una cita.','salud,recuperar,aplazar,semana,descansar','Hola, Emma. Soy Juana. Hoy, no te vi en la clase del español. ¿Dónde te has metido? Juan me ha dicho que tenías fiebre y dolor de garganta. ¿Es verdad lo que ha dicho? ¿Cómo te encuentras ahora? ¿Es grave tu enfermedad? Bueno, espero que te recuperes lo más rápido posible. Y si tienes cualquier necesidad, llámame por favor. En cuanto a la cita mañana, dado que no estás en un buen estado, creo que es mejor prorrogarla a la semana que viene. Podemos quedarnos en el restaurante cerca de tu casa y luego ir de compras. Sabes, tengo ganas de compartir contigo lo que me pasó últimamente. Pero, ahora, lo más importante para ti es tener un buen descanso y recuperarte cuanto antes. Espero a tu respuesta y que tengas un buen día. La salud es lo primero, así que es mejor aplazar la quedada hasta la semana que viene; necesitas descansar todo lo que puedas.'],
  ['retraso','跟对象说自己晚一点回家','Avise de que llegará tarde a casa, explique el trabajo pendiente y proponga una solución para la cena.','tarde,trabajo,cena,solución,perdón','Hola cariño, soy Luisa. Perdón por llamarte a estas horas, es que todavía estoy en la empresa. He terminado puntualmente la jornada; no obstante, al salir del trabajo he recibido una llamada de mi jefe y él me ha dicho que tendría que terminar un nuevo proyecto esta misma noche. Sin duda, es imposible que vuelva a casa antes de las 10. Entonces, para la cena, ojalá tengas que prepararla solo. Pero no te preocupes, ya he pedido todos los ingredientes que vas a necesitar a domicilio. Tengo confianza en tu talento al respecto. Y si tienes dudas, no olvides el internet, donde hay un montón de instrucciones detalladas. Estoy seguro/a de que podrás preparar una cena muy buena, la espero muchísimo. Besos, hasta luego. Si al final llego tarde, te llamo y buscamos una solución rápida, no te preocupes.'],
  ['oculista','眼睛不舒服，预约眼科医生','Pida una cita urgente con el oftalmólogo y describa los síntomas.','cita,ojo,dolor,urgente,síntomas','Buenos días, mi nombre es Manuel y el motivo por el que le llamo por teléfono es pedir una cita para ver mi médico de familia. Es que me duele muchísimo el ojo derecho. La verdad es que empecé a dolerme la semana pasada, después de nadar con mis amigos en una piscina que estaba cerca de su residencia, un insecto me picó el párpado derecho, como estamos en verano, no le di mucha importancia. Pero al día siguiente, sentí picor alrededor del ojo derecho. Ahora tengo hinchazón al lado del ojo y casi no veo nada. Por lo tanto, le pido una cita urgente para que me vea el médico enseguida, yo puedo ir a la consulta cuando me dé la cita. Muchas gracias por atenderme, muchas gracias. El dolor empieza por la mañana y los síntomas empeoran con la luz, por eso me urge tanto la cita.'],
  ['lost-luggage','丢失行李，要求经济援助','Informe de la pérdida de equipaje en un vuelo y solicite compensación económica.','maleta,vuelo,documentos,dinero,compensación','Buenos días. Mi nombre es Juan y mi número de pasaporte es E2032123. El motivo por el que les llamo por teléfono es el siguiente. Esta misma mañana he cogido un vuelo de Madrid a Barcelona contratando el servicio de su empresa aérea. Toda la trayectoria la he pasado sin ningún problema pero cuando he llegado hace una hora, me he dado cuenta de que mi maleta había desaparecido. No sé qué le ha ocurrido y cuándo podré recuperarla. Es una maleta roja en la que contiene mi carnet de conducir, mi documento de identidad y una carpeta con un contrato muy importante. Por eso, necesito mi maleta y en caso contrario, mi puesto de trabajo estará en peligro. Además, en la maleta también guardaba dos mil euros para pagar mis gastos de comida y alojamiento. Dada la situación actual, exijo una ayuda/compensación por un grave error que han cometido. Si ustedes pueden ofrecerme unos cien euros para poder alojarme en un hotel, será mucha ayuda para mí. Si consiguen localizar mi maleta, por favor, llámenme. Quedo esperando de sus noticias. Muchas gracias, hasta luego. Dentro llevaba también mis documentos y algo de dinero, por eso me urge tanto.'],
  ['cartera','商场丢钱包，说明情况','Informe de la pérdida de una cartera: aspecto, contenido, último lugar y datos de contacto.','cartera,perdí,documentos,lugar,teléfono','Buenos días, agente/señores. Mi nombre es Juan Luis Sánchez. El motivo por el que estoy aquí es el siguiente. Ayer, por descuido, perdí una cartera roja en la que contenía mi documento nacional de identidad, 3 cartas de créditos y 500 euros. Recuerdo que después de bajar del autobús 47, fui a un estanco para comprar un billete de metro para regresar a casa. Al pagar al dependiente, metí mi cartera en el bolsillo trasero de mi pantalón vaquero. En aquel entonces, un hombre de unos 50 años me empujó, me pidió perdón y salió enseguida del establecimiento. Sin prestarle atención a esto, volví a casa para dormir. Sin embargo, cuando mi mujer me pidió dinero, me di cuenta de que mi cartera había desaparecido. Estoy desesperado y no sé qué tengo que hacer ahora. Estoy casi seguro/a de que fue el hombre quien me robó la cartera. Agente, ¿me podría dar algún consejo? Muchas gracias por su tiempo y atención prestada. Le dejo también mi número de teléfono por si encuentra alguna pista luego. En la cartera había documentos muy importantes; la perdí cerca del lugar donde aparqué, en la calle Mayor.'],
  ['apartment','刚租的房子有东西坏了，希望房东来修','Solicite al propietario que repare algo que se ha averiado en el piso recién alquilado.','piso,alquilar,calefacción,contrato,derecho','Buenos días. Me llamo Marcos y hace una semana alquilé tu piso en el barrio Sol. Anoche, me trasladé a mi nuevo piso y me di cuenta de que la calefacción central no funcionaba. ¡Estoy enfadadísimo! De hecho, mi casa se ha convertido en un congelador y no dejo de estornudar. Supongo que estaré enfermo. Recuerdo que firmé un contrato en el que destacaba el buen funcionamiento de la calefacción central. Me parece que la situación actual es una violación de los derechos básicos de un inquilino. Espero que usted solucione este problema inmediatamente. En caso contrario, llamaré a la policía y juro que tomaré medidas legales contra usted. Hasta luego. Quiero seguir viviendo aquí y alquilar este piso a largo plazo, pero necesito que funcione todo.'],
  ['fiesta','通知朋友参加聚会，说明需要带的物品、时间地点','Invite a unos amigos a una fiesta y diga qué deben llevar, cuándo y dónde.','invitar,fiesta,lugar,hora,llevar','¡Buenos días, amigos! Hace ya tres años que no nos vemos. ¿Cómo es vuestra vida actual? La verdad es que os echo mucho de menos. Daniela me ha dicho que habéis terminado recientemente el Trabajo de Fin de Máster y habéis vuelto a China para pasar las vacaciones de verano. Como sabéis, mañana es mi cumpleaños y tengo intención de celebrar una fiesta con vosotros. A mí me gustaría celebrar la fiesta en el restaurante que está cerca de la casa de Miguel, como los viejos tiempos. Voy a organizar todo bien, pero ojalá podáis llevar una botella de vino de buena calidad para beber. En cuanto a la hora de empezar, ¿os viene bien las siete y media? Si no, también podemos aplazarla un poco. Estoy a la espera de vuestras respuestas. Hasta luego y un abrazo muy fuerte. Por eso quiero invitaros a mi fiesta; el lugar será el jardín de mi casa, hay sitio de sobra.'],
  ['sorpresa','为朋友组织惊喜派对，说明时间地点、需要带的物品、放什么音乐','Organice una fiesta sorpresa y reparta tareas entre los invitados.','sorpresa,reservar,bebidas,música,ayuda','¡Hola, amigos! ¿Qué tal? La verdad es que os echo mucho de menos. Daniela me ha dicho que Juan habéis vuelto a China. Como sabéis, mañana es su cumpleaños y tengo intención de celebrar una fiesta de sorpresa para él. Parece una buena idea, ¿verdad? No es posible organizarla por mí mismo; de modo que necesito vuestra ayuda. Creo que es mejor celebrar la fiesta en el restaurante que está cerca de la casa de Juan a las siete de la tarde, como los viejos tiempos. Voy a reservar una habitación y pedir los platos con anticipación. Ojalá podáis llevar unas botellas de vino y bebidas para beber. Además, las canciones populares son necesarias. En fin, ¿tenéis otros consejos? Estoy a la espera de vuestra respuesta. Hasta luego y un abrazo muy fuerte. También prepararemos música para bailar, sobre todo canciones que le gustan a ella.'],
  ['excursión','组织一场旅游，邀请朋友，说明自己的计划','Proponga un viaje con amigos: destino, transporte, actividades y presupuesto.','viaje,destino,transporte,actividades,presupuesto','¡Hola, amigos! ¿Qué tal? ¡Cuánto tiempo que no nos vemos! Me he enterado de que todos vosotros ya habéis vuelto a nuestro pueblo natal disfrutando de las vacaciones de verano. No es fácil que quedemos en la misma ciudad al mismo tiempo, por eso quería organizar un viaje para celebrarlo. A mi parecer, Qingdao es un destino ideal. Es una ciudad antigua, donde hay un montón de monumentos históricos. También es caracterizada por el mar limpio y la playa acogedora. Es una buena opción pasearnos por el parque al lado del mar, hacer picnic en la playa por la tarde, y probar el marisco y la cerveza de Qingdao para la cena. ¿Qué os parece este plan? En cuanto a los detalles, podremos hablar cara a cara después. Espero a vuestra respuesta. Hasta luego. Sobre el transporte, iremos en tren; entre las actividades están la visita al castillo y un paseo en barca, y el presupuesto total no pasa de cincuenta euros por persona.'],
  ['gimnasio','作为健身教练，讲为什么锻炼','Como entrenador/a, explique por qué conviene hacer ejercicio y proponga una rutina.','ejercicio,salud,rutina,recomiendo,empezar','Hola, todos. Soy Juana, una entrenadora del Gimnasio Madrid. Hoy voy a explicarles por qué necesitamos deporte. Como saben, es patente que las actividades deportivas favorecen la salud. Pues, lo que quería destacar no es su función curativa para nuestro cuerpo, sino para el estado psicológico. Según informes científicos, hacer deporte puede producir dopamina, la sustancia que nos hace sentir feliz y alegre. Ahora, estamos viviendo en una sociedad con competencia violenta. Por lo tanto, mucha gente padece de trastornos psicológicos, tales como ansiedad, estrés, depresión. Practicar deporte regular y moderadamente es el medicamento más seguro y sostenible sin ningún efecto secundario. ¡Hagan desde ahora! Recomiendo empezar poco a poco: primero ejercicio suave dos días por semana y, cuando el cuerpo se acostumbre, convertirlo en una rutina fija.']
];
