const SIELE_TOPIC_ZH={tecnología:'科技',educación:'教育',medioambiente:'环境',salud:'健康'};
SIELE_TOPICS_20.forEach(function(t){var topic='hf'+t.n;if(!SIELE_ORAL_BANK[4].some(function(x){return x.topic===topic;}))SIELE_ORAL_BANK[4].push({id:'t4-'+topic,topic:topic,sec:60,title:t.es,q:'¿Qué experiencia tiene con este tema? ¿Qué ventajas y problemas observa? ¿Qué medida propondría?',keys:['experiencia','ventaja','sin embargo','propondría','porque'],model:'Desde mi experiencia, <span class="key">'+t.es.toLowerCase()+'</span> es un tema cercano a la vida cotidiana. Por una parte ofrece oportunidades; <span class="link">sin embargo</span>, también plantea dificultades. Propondría combinar educación, responsabilidad y medidas concretas.'+(t.ext4||'')});if(!SIELE_ORAL_BANK[5].some(function(x){return x.topic===topic;}))SIELE_ORAL_BANK[5].push({id:'t5-'+topic,topic:topic,sec:240,title:t.es,q:'Presente una postura clara, dos argumentos, un contraargumento y una conclusión.',keys:['considero','por una parte','además','aunque','en definitiva'],model:'<span class="link">Me gustaría abordar</span> el tema de <span class="key">'+t.es.toLowerCase()+'</span>. Considero que tiene una influencia importante en la sociedad. Por una parte, puede aportar beneficios personales y colectivos; además, abre nuevas posibilidades. <span class="link">Aunque es cierto que</span> existen riesgos y opiniones contrarias, estos pueden reducirse mediante información, normas razonables y responsabilidad. <span class="key">En definitiva</span>, no se trata de aceptar o rechazar el fenómeno sin matices, sino de gestionarlo de forma equilibrada.'+(t.ext||'')});});
// PDF3 Tarea 4/5 扩充（10个新话题，含PDF原始范文）
const SIELE_TOPICS_EXTRA = [
  {n:21,es:'El cambio climatico y el efecto invernadero',t5model:'A medida de que la sociedad se desarrolla y evoluciona. Hoy en día, pretamos una mayor atención a ecosistema marino. Por eso, he elegido la opción una, dice que necesitamos proteger el ecosistema marino. Coincido con esta idea y a continuación, me gustaría proponer mis argumentos. Por un lado, quisiera destacar la importancia del ecosistema marino, que no solo es una parte muy importante de la tierra, sino que también los océanos cubren el 70 por ciento de la superficie de la tierra y apoyan casi la mitad de todas las especies en el planeta. Sirva como ejemplo, el gobierno se ha aprovechado de aprobar regulaciones con el objeto de proteger el ecosistema marino. Parece que se han visto resultados claros de éxito. Pero la situación sigue empeorando. Pongamos por caso, se estima que hasta 12 millones de toneladas de plástico llegan a los océanos. Esta contaminación afecta a más de 1300 especies. Por otro lado, las prácticas de pesca destructivas y sobrepesca provocan una crisis en los ecosistemas marinos. Considerando estos efectos, propongo algunas soluciones proactivas para impulsar el desarrollo de este sector. Aunque las medidas internacionales avancemos lentamente, cada acción local cuenta y cuenta mucho. Por una parte, los gobiernos deben acelerar la transición hacia las energías renovables y castigar la emisión sin control; por otra, los ciudadanos podemos reducir, reutilizar y exigir a las empresas productos limpios y envoltorios mínimos. Además, la educación ambiental convierte a cada alumno en un pequeño embajador del cambio, capaz de llevar las buenas prácticas a su propia casa. Considero que proteger el clima no es un coste sino la inversión más inteligente de nuestra época, porque el precio de no hacer nada lo pagaremos todos en inundaciones, sequías, incendios y migraciones forzadas que ya estamos empezando a ver. En definitiva, el efecto invernadero es un problema creado por el ser humano, y por eso mismo tiene solución humana, si actuamos juntos, con ciencia y sin más demora.', ext4:"La mayor ventaja de actuar ya es evitar daños mayores, porque cada tonelada de CO2 que no emitimos hoy es una inundación menos mañana. Yo propondría energía limpia en las escuelas y clases sobre el clima, aunque cueste inversión, porque educar hoy cuesta menos que reparar mañana."},
  {n:22,es:'Los efectos negativos del turismo',t5model:'Además de promover el crecimiento económico, el desarrollo del turismo contribuye al desarrollo de la sociedad en su conjunto. A medida de que la sociedad se desarrolla y evoluciona, hoy en día prestamos una mayor atención al turismo. Por eso, he elegido la opción una. Coincido con esta idea y a continuación, me gustaría proponer mis argumentos. Por un lado, quisiera destacar la importancia del turismo, que no solo fomenta el desarrollo económico, sino que también ayuda a los habitantes a obtener más puestos de trabajo, lo que es beneficioso para la estabilidad de la sociedad. Además, el turismo también juega un papel importante en la promoción del intercambio cultural y el enriquecimiento de la vida cotidiana de las personas. En cuanto a la cultura, el desarrollo del turismo puede promover el intercambio mutuo de culturas en diferentes regiones. Y es propicio para el desarrollo de la cultura tradicional. En cuanto a la vida social, cada vez más personas comienzan a utilizar el turismo como una forma de entretenimiento y ocio. Considerando estos efectos, propongo algunas soluciones proactivas para impulsar el desarrollo de este sector. Aunque el turismo llena las arcas municipales, sus efectos negativos exigen medidas urgentes y planificadas. Por una parte, las ciudades históricas sufren colas, ruido y alquileres que expulsan a los vecinos de sus propios barrios; por otra, los ecosistemas naturales se degradan rápidamente cuando los visitantes superan su capacidad real de carga. Además, el modelo de crucero o de escapada de un solo día deja poco dinero en el destino y mucha huella: basura, erosión y comercios convertidos en souvenirs genéricos. Considero que la solución está en gestionar con inteligencia, no en prohibir: tasas turísticas que se reinviertan en el destino, cupos en los lugares frágiles, promoción decidida de pueblos y temporadas bajas, y normas claras de convivencia. En definitiva, quien ama un lugar debe visitarlo de manera que ese lugar siga vivo para quienes lo habitan y para los viajeros que vendrán después de nosotros.', ext4:"La mayor ventaja de regular es proteger el destino, porque un barrio saturado deja de ser atractivo y la propia fuente de ingresos se seca. Yo propondría cupos en lugares frágiles y tasas reinvertidas, aunque los comercios protesten al principio, porque sin barrio no hay turistas que mantener."},
  {n:23,es:'Los vehiculos electricos: ventajas y desventajas',t5model:'A medida de que la sociedad se desarrolla y evoluciona, hoy en día prestamos una mayor atención a los vehículos eléctricos. Por eso, he elegido la opción una, que dice que el proceso de producción de los vehículos eléctricos tampoco es respetuoso con el medio ambiente. Coincido con esta idea y a continuación, me gustaría proponer mis argumentos. Por un lado, quisiera destacar las ventajas de los vehículos eléctricos: es una buena alternativa del uso del vehículo tradicional y es favorable para la protección medioambiental. Sirva como ejemplo, el gobierno se ha aprovechado de aprobar regulaciones con el objeto de impulsar el desarrollo de este sector. Por otro lado, los vehículos eléctricos son una espada de doble filo. Primero, todo el ciclo desde la producción hasta el reciclaje del automóvil no es completamente limpio debido a la necesidad de materiales altamente contaminantes y combustibles fósiles en el proceso de producción, porque las baterías de litio necesitan níquel que se extrae de la superficie de la tierra dañando el ecosistema. Aunque los vehículos eléctricos no son perfectos, representan el mejor paso disponible hacia un transporte más limpio. Por una parte, eliminan los gases de escape en las ciudades, donde respira la mayoría de la población, y su coste de uso por kilómetro es mucho menor que el del combustible; por otra, conviene seguir limpiando su fabricación, especialmente la extracción del litio y la generación eléctrica que los recarga. Además, las baterías duran hoy mucho más que hace una década y comienzan a reciclarse de forma industrial en varias fábricas europeas y asiáticas. Considero que el coche eléctrico es un eslabón de una cadena más amplia: menos coches en total, más transporte público, más bici y energía renovable para todo. En definitiva, apuesto por esta transición, pero con honestidad sobre sus límites y con inversiones públicas que la hagan accesible a todos los bolsillos, no solo a los más ricos, porque la sostenibilidad que excluye no es sostenible.', ext4:"Su mayor ventaja es la ciudad limpia, porque sin tubo de escape el aire de la calle cambia en meses. Falta limpiar su fabricación y las baterías. Yo propondría más puntos de carga y reciclaje industrial de baterías, aunque el precio baje despacio, porque el aire que respiran los niños no espera."},
  {n:24,es:'La educación a distancia vs. la educación presencial',t5model:'La educación escolar ofrece una variedad de beneficios y oportunidades que la educación a distancia puede no proporcionar. Los programas educativos en las escuelas están diseñados para brindar a los estudiantes una amplia gama de materias y experiencias de aprendizaje enriquecedoras. Esto contribuye al crecimiento integral de los niños. En las escuelas, los estudiantes tienen acceso a una amplia gama de asignaturas, que incluyen ciencias, matemáticas, historia, arte y deportes. Estas asignaturas brindan a los estudiantes la oportunidad de explorar diferentes áreas de conocimiento y descubrir sus talentos e intereses. Además, las escuelas ofrecen una estructura y un entorno propicio para el aprendizaje, con maestros capacitados que brindan orientación y apoyo. La educación escolar fomenta el desarrollo de habilidades sociales y emocionales en los niños. A través de la interacción con sus compañeros y la participación en actividades extracurriculares, los estudiantes aprenden a trabajar en equipo, a comunicarse y a resolver problemas. Si bien la educación a distancia puede ser conveniente en ciertas situaciones, es importante reconocer que la educación escolar ofrece una experiencia más completa y enriquecedora. Aunque la educación a distancia ganó muchos seguidores, mi experiencia me lleva a defender un modelo mixto y flexible. Por una parte, las clases online ofrecen flexibilidad, grabaciones para repasar a cualquier hora y acceso desde cualquier lugar del mundo, algo maravilloso para quien trabaja o vive lejos de las universidades; por otra, la educación presencial ofrece cosas difíciles de replicar: la mirada del profesor, el debate espontáneo, la amistad entre compañeros y la disciplina del aula. Además, los datos muestran que los alumnos con menos apoyo en casa sufren más en los formatos remotos, y la desigualdad educativa se agranda en lugar de reducirse. Considero que la mejor opción es combinar lo digital con lo humano: tecnología para practicar, repasar y personalizar, presencialidad para discutir, crear, colaborar y acompañar. En definitiva, la escuela del futuro no será a distancia ni presencial, sino inteligente, sabiendo cuándo usar cada herramienta, siempre al servicio del alumno y nunca al revés.', ext4:"Su mayor ventaja es la flexibilidad, porque estudias desde cualquier lugar y repasas las grabaciones mil veces. Su riesgo es la soledad y la desigualdad digital. Yo propondría un modelo híbrido con tutorías presenciales mensuales, aunque la logística sea compleja, porque la pantalla enseña pero no acompaña."},
  {n:25,es:'Las redes sociales y la privacidad',t5model:'Es cierto que en las redes sociales se puede encontrar información que no siempre es verídica. En la era digital, muchas personas utilizan las redes sociales para mostrar una versión idealizada de sus vidas, filtrando y seleccionando cuidadosamente lo que comparten. Esto puede generar una percepción distorsionada de la realidad. Es importante ser consciente de esta realidad y tener una actitud crítica al consumir información en las redes sociales. Debemos ser cautelosos y verificar la veracidad de lo que vemos y leemos. Es recomendable contrastar la información con fuentes confiables y buscar diferentes perspectivas antes de creer ciegamente en lo que se presenta en las redes sociales. Sin embargo, también es importante reconocer que no toda la información en las redes sociales es falsa. Las redes sociales también pueden ser una plataforma para compartir información valiosa, conectar con personas de ideas afines y acceder a diferentes puntos de vista. Depende de nosotros utilizarlas de manera responsable y crítica. Aunque las redes sociales han democratizado la comunicación, la privacidad se ha convertido en su víctima más silenciosa. Por una parte, compartimos fotos, ubicaciones y opiniones sin pensar en quién las guarda ni durante cuánto tiempo; por otra, las empresas convierten cada clic en un perfil comercial que nos sigue por toda la red y anticipa nuestras decisiones. Además, los datos filtrados alimentan estafas telefónicas y publicidad política manipulada, como se ha visto en varias campañas electorales en distintos países. Considero que se necesitan tres cosas al mismo tiempo: leyes más duras con las plataformas, educación digital desde la escuela y hábitos personales más prudentes, como revisar la configuración, limitar lo que publicamos y desconfiar de los permisos que damos sin leer. En definitiva, en internet nada es gratis: si no pagas con dinero, pagas con datos, y proteger la privacidad es proteger la propia libertad de decidir quién queremos ser en línea y qué parte de nuestra vida compartimos.', ext4:"La mayor ventaja de cuidarla es la libertad, porque quien controla tus datos termina condicionando tus decisiones. Yo reviso permisos y limito lo que público. Yo propondría leyes duras con las plataformas y clases de privacidad en los institutos, aunque la industria presione, porque el dato personal no debería ser moneda."},
  {n:26,es:'La belleza como concepto subjetivo',t5model:'La belleza es un concepto intrínsecamente subjetivo y personal. Cada individuo tiene una percepción única de lo que considera hermoso, basada en sus experiencias, valores y preferencias personales. Lo que puede parecer bello para una persona puede no serlo para otra. La belleza trasciende las definiciones estereotipadas y estándares impuestos por la sociedad. Es un reflejo de la diversidad y la individualidad humana. Cada persona tiene características y atributos únicos que pueden ser apreciados y considerados bellos por alguien. La belleza no se limita a la apariencia física, sino que también abarca la personalidad, el talento y la forma de ser. En definitiva, la belleza es un concepto personal y subjetivo que debe ser respetado en su diversidad. Aunque los medios de comunicación nos venden un canon único, la belleza es, en realidad, un espejo donde cada cultura y cada época se refleja de manera distinta. Por una parte, lo que hace un siglo se consideraba hermoso hoy puede parecer extraño, y los ideales cambian radicalmente de un país a otro; por otra, el auge de las redes ha empobrecido temporalmente esa diversidad, imponiendo filtros y cuerpos clónicos que dañan la autoestima de los jóvenes. Además, la industria cosmética mueve miles de millones explotando inseguridades que ella misma fabrica con su publicidad. Yo he aprendido a encontrar belleza en la risa de las personas mayores, en las manos trabajadas y en los rostros que nunca saldrán en una revista. Considero que la verdadera revolución es educar la mirada: enseñar a los niños que el talento, la bondad y la autenticidad son también formas de belleza. En definitiva, la belleza es subjetiva y plural, y quien la reduce a una plantilla empobrece la vida; abrazar su diversidad es un acto de libertad y de salud mental colectiva.', ext4:"Su mayor ventaja es la salud mental, porque aceptar la diversidad de cuerpos y rostros quita presión a los jóvenes. Los filtros venden un canon imposible. Yo propondría campañas con rostros reales y diversidad de edades, aunque la publicidad se resista, porque la belleza de verdad no pasa por una plantilla."},
  {n:27,es:'Los robots emocionales y la inteligencia artificial',t5model:'La capacidad de los robots para comprender plenamente las emociones humanas es un tema debatido en el campo de la inteligencia artificial. Si bien los avances tecnológicos han permitido a los robots detectar y responder a las señales emocionales de los seres humanos, es importante tener en cuenta que la comprensión emocional va más allá de la mera detección de expresiones faciales o tonos de voz. Las emociones humanas son complejas y están influenciadas por una variedad de factores individuales y contextuales. Requieren empatía, experiencia y conocimiento cultural para ser comprendidas en su totalidad. Los robots pueden ser programados para reconocer ciertos patrones y comportamientos emocionales, pero su capacidad de empatía y comprensión emocional genuina sigue siendo limitada. En resumen, aunque los robots pueden ser programados para detectar y responder a las señales emocionales, su capacidad para comprender plenamente las emociones humanas es limitada. La comprensión emocional profunda sigue siendo una habilidad distintivamente humana. Aunque los robots emocionales despiertan fascinación y miedo a partes iguales, yo creo que hay que analizarlos con serenidad y con datos. Por una parte, ya ayudan de verdad: acompañan a personas mayores que viven solas, asisten en terapias infantiles y enseñan habilidades sociales a alumnos con autismo; por otra, conviene no confundir la simulación de emociones con su experiencia real, porque una máquina puede imitar la compasión sin sentirla jamás. Además, plantean preguntas éticas nuevas: ¿debe un niño apegarse a un cuidador artificial?, ¿quién responde si un algoritmo consuela mal o manipula?, ¿qué datos emocionales recoge y a quién los vende? Considero que estas tecnologías son instrumentos valiosos siempre que complementen, y no sustituyan, el vínculo humano, y que hace falta regulación clara sobre datos, dependencia emocional y publicidad. En definitiva, la inteligencia artificial puede humanizar la tecnología si la usamos para fortalecer las relaciones, no para reemplazarlas, y esa frontera la decidimos nosotros con las leyes y con los hábitos que fijemos hoy.', ext4:"Su mayor ventaja es acompañar a quien está solo, porque un robot puede avisar de una caída y charlar cada tarde. Pero no sustituye un abrazo. Yo propondría usarlos como apoyo con supervisión humana, aunque despierten dudas, porque la tecnología ayuda cuando complementa y daña cuando reemplaza."},
  {n:28,es:'La superpoblación y sus consecuencias',t5model:'El exceso de población puede tener impactos irreversibles en el medio ambiente. A medida que la población mundial continúa creciendo, aumenta la demanda de recursos naturales, como agua, alimentos y energía. La explotación excesiva de estos recursos puede llevar a la degradación de los ecosistemas y la pérdida de biodiversidad. Además, el aumento de la población conlleva un mayor consumo y producción de bienes, lo que genera una mayor generación de residuos y contaminación. La deforestación, la contaminación del aire y del agua, así como el cambio climático, son algunas de las consecuencias negativas de la presión demográfica sobre el entorno. Es crucial abordar este desafío de manera sostenible, promoviendo el control de la natalidad, la planificación familiar y el desarrollo de políticas ambientales adecuadas. También es importante fomentar prácticas de consumo responsable y promover energías renovables. Solo a través de acciones colectivas y políticas adecuadas podemos mitigar los efectos negativos del exceso de población y proteger nuestro entorno para las generaciones futuras. Aunque la superpoblación parece un problema lejano, sus consecuencias ya se sienten en las grandes megaciudades del planeta. Por una parte, más de ocho mil millones de personas compiten por el agua, el suelo y los alimentos, y las presiones sobre los bosques y los océanos crecen año tras año; por otra, hay que evitar las alarmas falsas, porque la demografía no es un destino: las tecnologías, las políticas y los hábitos pueden cambiar la trayectoria, como ya se ha visto en varios países. Además, el desafío real no es solo el número, sino el consumo: un habitante del mundo rico deja una huella muchas veces mayor que uno del sur. Considero que las soluciones pasan por educar y empoderar a las mujeres, facilitar el acceso universal a la planificación familiar, producir alimentos de forma sostenible y repensar las ciudades para que gasten menos. En definitiva, el planeta puede acoger a todos si aprendemos a repartir mejor y a consumir con cabeza, y ese gran ajuste empieza en decisiones cotidianas que están a nuestro alcance.', ext4:"La mayor ventaja de planificar es evitar crisis, porque agua, suelo y comida no crecen al mismo ritmo que la población. Yo propondría educación y acceso universal a la planificación familiar, aunque choque con costumbres, porque decidir con libertad es la base de cualquier solución duradera. Las ciudades también pueden crecer hacia arriba y no hacia fuera."},
  {n:29,es:'Los videojuegos y los adolescentes',t5model:'El impacto de los videojuegos en los adolescentes es un tema ampliamente debatido. Algunas personas sostienen que los videojuegos pueden llevar a los adolescentes a volverse más introvertidos y a aislarse socialmente. Sin embargo, considero que esta afirmación es generalizada y simplista. Si bien es cierto que el uso excesivo de los videojuegos puede resultar en un aislamiento social si se descuida la interacción personal, no todos los adolescentes que juegan videojuegos experimentan este efecto. Los videojuegos también pueden ofrecer una forma de socialización y conexión con otros jugadores a través de experiencias compartidas en línea. Además, los videojuegos pueden promover habilidades cognitivas y sociales. Muchos juegos requieren estrategia, resolución de problemas y toma de decisiones rápida, lo que puede mejorar las habilidades cognitivas de los adolescentes. Los videojuegos multijugador en línea pueden fomentar la cooperación, la comunicación y el trabajo en equipo. Sin embargo, es importante establecer límites saludables en cuanto al tiempo dedicado a los videojuegos y promover una variedad de actividades. En resumen, los videojuegos no necesariamente conducen a la autoexclusión en los adolescentes si se usan de manera equilibrada. Aunque a los videojuegos se les culpa de muchos males, la investigación actual es mucho más matizada que los titulares. Por una parte, los juegos entrenan la memoria, la atención y la resolución de problemas, y los títulos cooperativos crean amistades reales, incluso entre continentes; por otra, el riesgo aparece con el exceso: horas robadas al sueño, al estudio y al deporte, y alguna dificultad para desconectar. Además, los contenidos deben adaptarse siempre a la edad, y ahí los padres son la primera barrera, más importante que cualquier etiqueta. Considero que prohibir no funciona, acompañar sí: jugar con los hijos, poner horarios claros y ofrecer alternativas atractivas como el deporte, la música o los juegos de mesa en familia. En definitiva, los videojuegos son una cultura con sus propias reglas, y como cualquier cultura, enriquece o empobrece según cómo la consumamos; la clave sigue siendo el equilibrio que enseñamos en casa, con ejemplo más que con sermones.', ext4:"Su mayor ventaja es cognitiva, porque muchos juegos entrenan la memoria, la estrategia y el trabajo en equipo. El problema es el exceso de horas. Yo propondría horarios claros y jugar con los hijos de vez en cuando, aunque cueste tiempo, porque lo que se acompaña no se descontrola."},
  {n:30,es:'Las compras por internet vs. las tiendas fisicas',t5model:'Es cierto que las compras en línea pueden estimular el deseo de compra de los consumidores y llevarlos a adquirir más productos. La comodidad de comprar desde casa y la disponibilidad de una amplia variedad de opciones en línea pueden influir en el comportamiento del consumidor. Las tiendas en línea suelen utilizar estrategias de marketing digital, como recomendaciones personalizadas y promociones especiales, para atraer a los consumidores y alentarlos a comprar más. Además, la posibilidad de comparar precios y leer reseñas de otros clientes puede generar un impulso de compra. Sin embargo, es importante que los consumidores sean conscientes de sus necesidades reales y establezcan límites en sus compras en línea. La tentación de gastar más de lo necesario puede ser fuerte, por lo que es fundamental tener un control consciente sobre los hábitos de consumo. En última instancia, cada consumidor es responsable de tomar decisiones informadas y racionales al hacer compras en línea. Si se utiliza de manera adecuada, el comercio electrónico puede ser una herramienta conveniente y beneficiosa. Aunque comprar por internet sea cómodo y rápido, yo defiendo un consumo consciente que sepa cuándo usar cada canal. Por una parte, la red ofrece precio, variedad instantánea y las opiniones de otros compradores, y resulta ideal para productos estandarizados como libros, electrónica o repuestos; por otra, las tiendas físicas ofrecen asesoramiento humano, la posibilidad de probar y la devolución inmediata, algo muy valioso en ropa, calzado o alimentación fresca. Además, el comercio local sostiene empleos y vida de barrio que ninguna logística centralizada puede reemplazar: detrás de cada tienda hay una familia que paga impuestos y apoya actividades del barrio. Considero que el futuro pertenece al modelo híbrido: investigar en línea y comprar donde convenga, exigiendo a las plataformas transparencia fiscal y a los negocios cercanos experiencia y servicio impecables. En definitiva, la pregunta no es online contra tienda, sino consumidor inteligente contra consumidor pasivo, y educar esa inteligencia es tarea de escuelas, de familias y de cada uno de nosotros.', ext4:"Su mayor ventaja es el precio y la comparación, porque en dos minutos revisas diez tiendas sin salir de casa. Pero probar y tocar solo es posible en la calle. Yo propondría comprar online lo estandarizado y en la tienda lo que necesite consejo, aunque sea más caro, porque el asesoramiento también es parte del producto."}
];
SIELE_TOPICS_EXTRA.forEach(function(t){var topic='hf'+t.n;if(!SIELE_ORAL_BANK[4].some(function(x){return x.topic===topic;}))SIELE_ORAL_BANK[4].push({id:'t4-'+topic,topic:topic,sec:60,title:t.es,q:'¿Qué experiencia tiene con este tema? ¿Qué ventajas y problemas observa? ¿Qué medida propondría?',keys:['experiencia','ventaja','sin embargo','propondría','porque'],model:'Desde mi experiencia, '+t.es.toLowerCase()+' es un tema muy relevante. Por una parte ofrece oportunidades; sin embargo, también plantea dificultades. Propondría combinar educación, responsabilidad y medidas concretas.'+(t.ext4||'')});if(!SIELE_ORAL_BANK[5].some(function(x){return x.topic===topic;}))SIELE_ORAL_BANK[5].push({id:'t5-'+topic,topic:topic,sec:240,title:t.es,q:'Presente una postura clara, dos argumentos, un contraargumento y una conclusión.',keys:['considero','por una parte','además','aunque','en definitiva'],model:t.t5model});});
// ===== 口语真题题库管理员编辑（content_edits.oralbank，全量覆盖存储） =====
let _obadmBank = null;
function _oralBankClone(){ var out={}; [1,2,3,4,5].forEach(function(n){ out[n]=(getSieleOralBank()[n]||[]).map(function(q){return JSON.parse(JSON.stringify(q));}); }); return out; }
function renderOralBankAdmin(keep){
  if(!keep) _obadmBank = _oralBankClone();
  var tareaNames = {1:'Tarea 1 · 短答',2:'Tarea 2 · 看图描述',3:'Tarea 3 · 情景对话',4:'Tarea 4 · 话题表达',5:'Tarea 5 · 议论文'};
  var h = '<div style="padding:6px 0"><h2>🔧 管理员编辑口语真题题库</h2><div class="sub" style="margin-bottom:10px">Tarea 1-5 全部题目，每题可编辑题目描述/内容/范例答案/关键词，支持增删改。保存后覆盖到所有用户。</div>';
  [1,2,3,4,5].forEach(function(n){
    var list = _obadmBank[n]||[];
    h += '<div class="card" style="margin:10px 0">';
    h += '<h3 style="margin-bottom:6px">'+esc(tareaNames[n])+' <span class="sub" style="font-size:12px">'+list.length+' 题</span></h3>';
    list.forEach(function(q, qi){
      h += '<div style="border:1px dashed var(--line);padding:8px;margin:6px 0;border-radius:6px;background:#fafafa">';
      h += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px"><span style="font-size:11px;color:var(--soft)">题 '+(qi+1)+'</span><button class="btn xs dgr" onclick="delOralBankQ('+n+','+qi+')">✕ 删除</button></div>';
      if(q.title) h += '<div style="margin:3px 0;font-size:12px"><b>标题：</b><input id="obadm_title_'+n+'_'+qi+'" value="'+esc(q.title)+'" style="width:100%"></div>';
      h += '<div style="margin:3px 0;font-size:12px"><b>题目描述：</b><textarea id="obadm_q_'+n+'_'+qi+'" rows="2" style="width:100%;font-size:12px">'+esc(q.q||'')+'</textarea></div>';
      h += '<div style="margin:3px 0;font-size:12px"><b>范例答案：</b><textarea id="obadm_model_'+n+'_'+qi+'" rows="4" style="width:100%;font-size:12px;font-family:var(--serif)">'+esc(q.model||'')+'</textarea></div>';
      h += '<div style="margin:3px 0;font-size:12px"><b>关键词：</b><input id="obadm_keys_'+n+'_'+qi+'" value="'+esc((q.keys||[]).join(', '))+'" style="width:100%"><span class="sub" style="font-size:10px">逗号分隔</span></div>';
      h += '<div style="display:flex;gap:8px;margin:3px 0;font-size:12px"><div><b>时长(秒)：</b><input id="obadm_sec_'+n+'_'+qi+'" value="'+esc(String(q.sec||''))+'" style="width:60px"></div></div>';
      h += '</div>';
    });
    h += '<button class="btn sm" onclick="addOralBankQ('+n+')">➕ 加题</button>';
    h += '</div>';
  });
  h += '<div style="display:flex;gap:8px;margin:12px 0"><button class="btn pr" onclick="saveOralBankAdmin()">💾 保存并同步给所有用户</button><button class="btn ol" onclick="renderMain()">❌ 取消</button></div></div>';
  var m = document.getElementById('main');
  if(m) m.innerHTML = h;
  window.scrollTo(0,0);
}
function addOralBankQ(n){
  if(!_obadmBank) return;
  _obadmBank[n] = _obadmBank[n]||[];
  _obadmBank[n].push({id:'t'+n+'_new_'+Date.now().toString(36),sec:10,q:'',keys:[],model:''});
  renderOralBankAdmin(true);
}
function delOralBankQ(n, qi){
  if(!_obadmBank||!_obadmBank[n]) return;
  if(!confirm('确定删除 Tarea '+n+' 第 '+(qi+1)+' 题？')) return;
  _obadmBank[n].splice(qi,1);
  renderOralBankAdmin(true);
}
function saveOralBankAdmin(){
  if(!_obadmBank) return;
  var bank = {};
  [1,2,3,4,5].forEach(function(n){
    var list = _obadmBank[n]||[];
    var out = [];
    for(var qi=0; qi<list.length; qi++){
      var q = list[qi];
      var o = {id:q.id||('t'+n+'_'+qi), sec:Number((document.getElementById('obadm_sec_'+n+'_'+qi)||{}).value||q.sec||10)};
      var titleEl = document.getElementById('obadm_title_'+n+'_'+qi);
      if(titleEl) o.title = titleEl.value;
      o.q = (document.getElementById('obadm_q_'+n+'_'+qi)||{}).value||'';
      o.model = (document.getElementById('obadm_model_'+n+'_'+qi)||{}).value||'';
      var keysVal = (document.getElementById('obadm_keys_'+n+'_'+qi)||{}).value||'';
      o.keys = keysVal.split(',').map(function(k){return k.trim();}).filter(Boolean);
      if(q.topic) o.topic = q.topic;
      if(q.formal!==undefined) o.formal = q.formal;
      if(q.photo!==undefined) o.photo = q.photo;
      out.push(o);
    }
    bank[n] = out;
  });
  window._deleSyncContentEdits('oralbank', {bank: bank});
  window._contentEdits.oralbank = {bank: bank};
  toast('✅ 已保存并同步给所有用户','ok');
  renderMain();
}

// 获取最终口语真题题库（管理员编辑 > 默认），全量覆盖
window.SIELE_T3_META={"t3-mascota":{"cat":"请求类","esTitle":"Pedir un favor: cuidar a su mascota","zhExplain":"情境：您要短期出门旅行，请朋友帮忙照看宠物。要点：① 问候并寒暄几句；② 解释为什么需要朋友帮忙照看；③ 说明宠物需要的照料并表达感谢（范文中为照顾小狗 Banana 近一个月）。","q":"Usted debe hacer un viaje corto y le pide a un amigo que cuide a su mascota. Usted tiene que:\n1. Saludar y hacer alguna pregunta personal;\n2. Explicar las razones por las que necesita que cuide a su mascota;\n3. Decir los cuidados que necesita su mascota y agradecer el favor.","model":"Buenas tardes, soy Gonzalo. Hace mucho que no nos vemos, ¿cómo estás? Te llamo para pedirte un favor. Resulta que la semana que viene iré a visitar Madrid con mi amiga, pero mis familiares no pueden ayudarme a cuidar a mi mascota. ¿Podrías encargarte de mi perro, Banana, durante casi un mes? A él le gusta comer frutas y explorar en jardines. No necesitas hacer más que darle comida y agua dos veces al día. Sabes que eres mi mejor amigo, y como agradecimiento, te traeré un regalo interesante cuando regresemos a casa. Si puedes, llámame por favor. Aprecio mucho tu tiempo. ¡Que tengas un buen día! ¡Chao!"},"t3-plantas":{"cat":"请求类","esTitle":"Pedir que riegue sus plantas en vacaciones","zhExplain":"情境：您要出门度假，请朋友帮忙照看家里的植物。要点：① 问候并说明请求；② 交代浇水频率与钥匙存放处；③ 说明工具位置并致谢（范文中为每周浇一次水、钥匙放在邻居处、洒水壶在阳台，还留邻居电话备急）。"},"t3-vivienda":{"cat":"请求类","esTitle":"Informar de una avería y pedir reparación","zhExplain":"情境：租住房屋暖气失灵，致电房东要求紧急维修。要点：① 说明身份与故障情况；② 强调合同写明设备完好、家中有婴儿等紧急因素；③ 要求立即派技师并索要临时方案（范文中为请技师今天上门，否则至少告知上门时间与过渡办法）。"},"t3-oculista":{"cat":"请求类","esTitle":"Pedir una cita urgente con el oculista","zhExplain":"情境：游泳后眼睛红肿疼痛、看东西模糊，致电诊所加急约眼科。要点：① 问候并自报姓名；② 说明从何时开始、现在症状如何；③ 要求本周加急就诊并说明可前往的时间（范文中为周末游泳后左眼持续疼痛发红）。","q":"Usted quiere pedir una cita urgente porque no ve bien. Usted llama a una clínica y tiene que:\n1. Saludar e informar de su situación.\n2. Explicar desde cuándo le pasa y cómo se siente;\n3. Pedir una cita urgente y decir cuándo puede ir.","model":"Buenas tardes, soy Gonzalo. Te llamo para pedir una cita urgente con mi médico. Resulta que el fin de semana pasado fui a una piscina con mis amigos para divertirnos, pero al regresar a casa, empecé a sentir dolor en los ojos. Hasta ahora, el ojo izquierdo me duele mucho y tengo enrojecimiento alrededor de los ojos. Por eso, quisiera pedir ayuda del oculista y me gustaría programar una cita para esta semana. Si tienes alguna duda, por favor, llámame. Aprecio mucho tu atención. ¡Que tengas un buen día! ¡Chao!"},"t3-apartment":{"cat":"请求类","esTitle":"Solicitar la reparación del piso","zhExplain":"情境：刚搬进新租的房子就发现中央暖气不工作，致电房东交涉。要点：① 自报姓名与入住时间；② 描述寒冷处境并援引合同承诺；③ 要求立即维修（范文中还以报警和采取法律行动施压，同时表明想长租此房的意愿）。"},"t3-sick-day":{"cat":"请求类","esTitle":"Reportar que no va a poder ir a trabajar","zhExplain":"情境：家人突发疾病住院，您无法上班，致电公司请假。要点：① 问候并致歉；② 说明不能到岗的原因；③ 提出返岗与补工安排（范文中为母亲动物毛发过敏住院、请两天假、周三返岗）。","q":"Usted tiene un problema y no puede ir a trabajar. Usted tiene que:\n1. Saludar y disculparse por no poder ir a trabajo;\n2. Explicar las razones por las que no puede ir a trabajar;\n3. Proponer la forma en que recuperará el día de trabajo.","model":"Buenas tardes, soy Gonzalo. ¿Cómo estás? Te llamo para solicitar un permiso. Esta mañana recibí una llamada de mi madre; ha tenido una reacción alérgica al pelo de los animales y está bastante enferma, así que ahora estoy en el hospital con ella. No estoy seguro de poder regresar puntualmente a la empresa. Lamento informarte que necesitaré tomar dos días libres y regresaré a trabajar el miércoles. Si es posible, llámame por favor. Aprecio mucho tu comprensión. ¡Que tengas un buen día! ¡Chao!"},"t3-restaurant-reserve":{"cat":"请求类","esTitle":"Reservar una mesa en un restaurante","zhExplain":"情境：致电餐厅为周六晚的生日聚餐预订餐桌。要点：① 说明人数与时间并给备选时段；② 提出露台座位、生日蛋糕等要求；③ 询问是否需定金并留电话（范文中为六人、九点半或十点、想点海鲜饭和塔帕斯分享）。"},"t3-exchange-book":{"cat":"请求类","esTitle":"Cambiar un libro","zhExplain":"情境：朋友送的书与您已有的一本重复，想拿去书店更换。要点：① 说明书是上周买的；② 解释想换的原因；③ 告诉店员您喜欢的类型并约时间（范文中为换一本悬疑小说充实课余生活、约下午五点到店）。","q":"Un amigo le ha regalado un libro y usted quiere cambiarlo. Usted habla con el dependiente de la librería y tiene que:\n1. Decir cuándo le compraron el libro.\n2. Explicar por qué quiera cambiarlo.\n3. Contarle qué tipo de libros le gustan.","model":"¡Buenas tardes, soy Gonzalo! Te llamo para hacer un cambio con un libro que mi mamá compró en tu tienda la semana pasada. Este libro es una excelente opción para mis estudios, pero ya tengo uno similar. Me gustaría cambiarlo por una novela de suspense que pueda enriquecer mi tiempo libre después de la escuela. Si es posible, me gustaría visitar tu tienda a las cinco de la tarde para hacer el intercambio. Si tienes alguna duda o solicitud, por favor, llámame. Aprecio mucho tu atención. ¡Que tengas un buen día! ¡Hasta luego!"},"t3-borrow-book":{"cat":"请求类","esTitle":"Pedir prestado un libro de texto","zhExplain":"情境：历史课本丢了而书店断货，向同学借书复习备考。要点：① 说明缺哪本书、为何买不到；② 承诺保管好并限期归还；③ 主动以自己的书作交换（范文中为西班牙史课本、最迟下周五归还、还提到是同学 Andrés 推荐来借的）。"},"t3-rent-house":{"cat":"请求类","esTitle":"Pedir información sobre el alquiler de una casa","zhExplain":"情境：您在找房，网上看中一套，直接联系房东。要点：① 问候并说明从哪里得知房子空着；② 解释为什么想租；③ 说明您什么时候可以去看房（范文中为下月来京工作、三居室、约下周二下午看房面谈）。","q":"Usted está buscando casa y ha visto en internet una que le interesa, así que habla con el propietario. Usted tiene que:\n1. Saludar y decir cómo supo que la casa estaba libre;\n2. Explicar por qué quiere alquilarla;\n3. Decir cuándo puede usted visitar la casa.","model":"Buenas tardes, soy Gonzalo. Te llamo para consultar sobre el alquiler de un apartamento. Mi amigo y yo estaremos en Beijing por trabajo el próximo mes, y estamos interesados en alquilar una casa para facilitar nuestras actividades laborales y la vida cotidiana. Estamos buscando una casa con tres habitaciones. Hemos escuchado hablar de una casa en la calle Chaoyang, hemos visto fotos en línea y nos ha llamado mucho la atención. Quisiera obtener más información sobre el costo y otros detalles de la casa. Si es posible, nos gustaría visitar la propiedad en la tarde del próximo martes. En ese momento, podríamos discutir los detalles en persona. Esperamos tu respuesta y agradecemos de antemano tu atención. ¡Chao!"},"t3-help-move":{"cat":"请求类","esTitle":"Pedir ayuda con la mudanza","zhExplain":"情境：下周末搬家，东西太多一个人搬不动，请朋友帮忙。要点：① 说明日期、时间与新住址；② 说明要搬的物品并借用他的货车；③ 承诺请客答谢（范文中为周六九点到中午、Chamberí 新居、请帮忙的人吃披萨喝啤酒）。"},"t3-late-to-work":{"cat":"请求类","esTitle":"Pedir permiso al jefe","zhExplain":"情境：您要带儿子去看医生，上班会迟到，向老板请示。要点：① 问候并说明孩子怎么了；② 请求晚点到岗；③ 提出补足工作时间的办法（范文中提出晚上加班补上午的任务）。","q":"Usted tiene que llevar a su hijo al médico y va a llegar tarde al trabajo. Usted habla con su jefe y tiene que:\n1. Saludar y explicarle qué le pasa a su hijo;\n2. Pedirle permiso para llegar tarde;\n3. Proponerle una solución para completar su horario de trabajo.","model":"Buenas tardes, soy Gonzalo. ¿Cómo estás? Te llamo por teléfono para pedir un permiso. Esta mañana recibí una llamada de mi hijo; lamentablemente, ha tenido una reacción alérgica al pelo de animal y está bastante enfermo. En este momento, estoy en el hospital con él y no estoy seguro de poder regresar puntualmente a la empresa. Lamento la situación, pero me gustaría pedir permiso para llegar tarde. Además, estaré dispuesto a trabajar horas extras esta noche para ponerme al día con las tareas de la mañana. Agradezco tu comprensión y espero tu respuesta. ¡Que tengas un buen día! Chao."},"t3-rent-car":{"cat":"请求类","esTitle":"Alquilar un coche","zhExplain":"情境：您在这座城市游览，想租车多看看，到租车行咨询。要点：① 说明为什么需要车；② 说明想要什么车型；③ 询问租赁条件细节（范文中六人要 SUV，问租金、油费、保险并请邮件答复）。","q":"Está de visita en la ciudad y quiere alquilar un coche para ver más cosas. Acude a una agencia de alquiler de coches. Tiene que:\n1. Explicar por qué necesita un coche;\n2. Explicar qué tipo de coche quiere;\n3. Pedir detalles sobre las condiciones de alquiler.","model":"Buenas tardes, soy Gonzalo. Te llamo para consultar sobre el alquiler de un coche. Mi familia y yo visitaremos Beijing esta tarde, y estamos interesados en alquilar un automóvil para que sea más conveniente explorar diversos lugares y atracciones. Preferiríamos un SUV, ya que somos seis personas y necesitamos seis plazas. Además, me gustaría obtener información sobre los costos, como el alquiler, el combustible y el seguro. ¿Podrías enviarme un correo electrónico con los detalles? Esperamos con interés tu respuesta y agradecemos tu atención. ¡Que tengas un buen día! ¡Chao!"},"t3-pick-up-daughter":{"cat":"请求类","esTitle":"Pedir un favor: recoger a su hija","zhExplain":"情境：您在医院陪护突发疾病的母亲，无法去学校接女儿，请好友帮忙。要点：① 问候并请他去接女儿；② 解释今天为何去不了；③ 以其他方式答谢并道别（范文中为母亲过敏住院、邀请明晚在他家附近的餐厅请他吃饭）。","q":"Usted no puede ir a recoger a su hija a la escuela y habla con un amigo. Usted tiene que:\n1. Saludar y pedirle a su amigo que vaya a buscar a su hija;\n2. Explicar por qué usted no puede ir hoy a la escuela;\n3. Ofrecerle su ayuda con otras cosas y despedirse.","model":"Buenas tardes, soy Gonzalo. Hace mucho que no nos vemos, ¿cómo estás? Te llamo para pedirte un favor: necesito que vayas a buscar a mi hija a la escuela. Esta mañana recibí una llamada de mi madre; ha tenido una reacción alérgica a la piel de los animales y está bastante enferma. Ahora estoy en el hospital con ella, y no estoy seguro de poder ir a la escuela antes de la tarde. Sabes que eres mi mejor amigo, y como agradecimiento, quiero invitarte a cenar mañana por la noche en el restaurante cerca de tu casa. ¿Qué te parece? Si tienes alguna duda, por favor, llámame. Aprecio mucho tu tiempo. ¡Que tengas un buen día! ¡Chao!"},"t3-translate-email":{"cat":"请求类","esTitle":"Pedir ayuda","zhExplain":"情境：收到一封重要但看不懂的外语邮件，周末前必须转交老板。要点：① 问候并说明发生了什么；② 解释为什么需要他帮忙讲解；③ 约一个见面时间（范文中为邮件来自外国客户、提议周五碰面）。","q":"A usted le ha llegado un mail importante, pero está en otro idioma que usted no sabe, así que pide ayuda a un amigo suyo para que le explique.\n1. Saludar y decirle que ha pasado.\n2. Explicarle por qué necesita su ayuda.\n3. Quedar para un tiempo.","model":"Buenas tardes, soy Gonzalo. Hace mucho que no nos vemos, ¿cómo estás? Te llamo para pedirte un favor. Esta mañana recibí un correo electrónico importante de mi cliente extranjero, pero está en un idioma que no domino. Tendré que enviárselo a mi jefe este fin de semana, así que quisiera pedirte ayuda para que me lo expliques. Si puedes, ¿qué te parece si nos encontramos el viernes? Si tienes dudas, llámame por favor. Aprecio mucho tu tiempo. ¡Que tengas un buen día! ¡Chao!"},"t3-borrow-house":{"cat":"请求类","esTitle":"Pedirle a un amigo poder organizar una fiesta en su casa","zhExplain":"情境：下周末想办一场家乡传统节日的聚会（范文中为中秋节），但自己家太小，想借朋友家。要点：① 问候并问他能不能借地方办；② 说明聚会怎样、会有谁来；③ 告知日期时间以及需要准备什么（食物、饮料）。","q":"Usted quiere celebrar una fiesta tradicional de su país el próximo fin de semana, pero su casa es muy pequeña, por lo que llama a un amigo para pedirle si puede hacerla en su casa. Usted tiene que:\n1. Saludar y preguntar si puede hacer la fiesta en su casa;\n2. Explicar cómo va a ser la fiesta y quién va a ir;\n3. Informarle del día y la hora, y de lo que necesita para la fiesta.","model":"Buenas tardes, soy Gonzalo. Te llamo por teléfono para discutir contigo la posibilidad de organizar una fiesta en tu casa. La próxima semana celebraremos nuestro Festival Chino del Medio Otoño, y en nuestro país, las familias y amigos suelen reunirse para cenar y participar en diversas actividades. Por lo tanto, me gustaría organizar una fiesta aquí para celebrar este festival. Sin embargo, mi casa es demasiado pequeña, por lo que estoy considerando la opción de hacerlo en tu casa. Podríamos invitar a algunos compañeros de clase y amigos. Si estás de acuerdo, hemos pensado en estar en tu casa el próximo miércoles a las cinco de la tarde. También necesitaríamos preparar algo de comida y bebida. Agradecemos tu consideración. ¡Que tengas un buen día!"},"t3-pharmacy-advice":{"cat":"请求类","esTitle":"Pedir consejo en la farmacia","zhExplain":"情境：身体不适，到值班药店向店员咨询。要点：① 问候并描述症状；② 说明以前是否出现过；③ 请教如何缓解（范文中为周末游泳后左眼红肿疼痛、此前已发生过两次，想咨询缓解办法）。","q":"Usted va a la farmacia de guardia porque se encuentra mal. Usted habla con el dependiente y tiene que:\n1. Saludar y explicar cómo se siente;\n2. Decir si le ha pasado otras veces;\n3. Pedir consejos para encontrarse mejor.","model":"Buenas tardes, señor, mi nombre es Gonzalo. Necesito pedirte ayuda para aliviar mi malestar. Resulta que el fin de semana pasado fui a una piscina con mis amigos para divertirnos, pero cuando regresamos a casa, empecé a sentir dolor en los ojos. Hasta ahora, me duele mucho el ojo izquierdo y tengo enrojecimiento alrededor de los ojos. He experimentado esta condición dos veces antes y esta vez quisiera consultar cómo aliviar estos síntomas. Agradecería mucho tu atención."},"t3-cena":{"cat":"邀请类","esTitle":"Invitar a un amigo extranjero a comer con su familia","zhExplain":"情境：您想请外国朋友来家里和家人一起吃饭。要点：① 发出邀请；② 解释为什么想请他来家里吃饭；③ 提出见面日期和钟点（范文中家人想认识他、准备中式家宴、还帮推荐景点）。","q":"Usted lleva a comer a un amigo extranjero con su familia. Usted tiene que:\n1. Invitarle;\n2. Explicar los motivos por los que quiere llevarle a comer con su familia;\n3. Proponer el día y la hora para quedar.","model":"Buenas tardes, soy Gonzalo. Te llamo por teléfono para invitarte a mi casa a cenar con mi familia. Sabes, eres mi mejor amigo en España, y a mi familia le encantaría conocerte cuando se enteren de que estás de visita en China. Nos gustaría prepararte una cena china especial en casa; créeme, será muy deliciosa. Además de esto, también podemos charlar juntos y recomendarte atracciones turísticas en China. Si puedes, nos encantaría que estuvieras en mi casa este sábado a las cinco de la tarde. Espero tu respuesta. ¡Que tengas un buen día! ¡Chao!"},"t3-boda":{"cat":"邀请类","esTitle":"Invitar a una boda","zhExplain":"情境：几个月后您要结婚，想邀请住在国外、久未见面的表亲。要点：① 问候并告知结婚的消息；② 讲讲您和未婚妻是怎么认识的；③ 正式邀请并说明婚礼的时间与安排（范文中含 3 月 5 日、MingDu 酒店、地铁 3 号线）。","q":"Usted se casa dentro de unos meses y quiere invitar a un primo que vive en otro país y que hace tiempo que no ve. Usted lo llama y tiene que:\n1. Saludar y darle la noticia de su boda.\n2. Explicarle cómo conoció a su novia.\n3. Invitarle a la boda e informarle de cuándo y cómo será.","model":"Buenas tardes, soy Gonzalo. Te llamo por teléfono para invitarte a mi boda. Estoy emocionado en este momento porque me voy a casar el próximo mes y estaría muy feliz de verte ese día. Conocí a mi novia en la universidad; siempre me ayudaba cuando estaba en problemas, y la he cuidado bien en mi vida. Poco a poco nos conocimos, nos comunicamos y nos enamoramos. Nuestra boda está programada para el 5 de marzo. Invitaré a amigos y familiares, tanto del país como del extranjero. Prepararemos comida y actuaciones para celebrar la boda juntos. Será un gran día. El evento se llevará a cabo en el hotel MingDu, y puedes llegar directamente a la plaza frente al hotel tomando la línea 3 del metro. Esperamos contar con tu presencia. Gracias por tu tiempo. ¡Qué tengas un buen día! ¡Chao!"},"t3-fiesta":{"cat":"邀请类","esTitle":"Invitar a una fiesta en casa","zhExplain":"情境：明天是您的生日，邀请三年未见的老友来家里聚会。要点：① 说明聚会时间与地点；② 请大家带上红酒等饮品；③ 表达重逢的期待（范文中为晚上七点半开始，请每人带一瓶好酒，等大家回复确认）。"},"t3-sorpresa":{"cat":"邀请类","esTitle":"Organizar una fiesta sorpresa","zhExplain":"情境：明天是 Juan 的生日，您组织惊喜派对并向朋友们分工。要点：① 交代时间地点并强调保密；② 分派各自要带的酒水；③ 安排音乐等细节（范文中为下午七点在他家附近餐厅包间、提前订菜，请大家带酒并放他爱听的歌）。"},"t3-excursión":{"cat":"邀请类","esTitle":"Proponer un viaje con amigos","zhExplain":"情境：趁暑假大家回乡，提议组织一次青岛之旅。要点：① 介绍目的地特色；② 说明交通与活动安排；③ 给出预算（范文中为坐火车前往、海边散步野餐、参观城堡乘船游，人均不超过五十欧）。"},"t3-charity":{"cat":"邀请类","esTitle":"Invitar a una actividad benéfica","zhExplain":"情境：邀请朋友参加为孤儿募捐的慈善跑。要点：① 说明活动目的与善款去向；② 告知时间地点与报名费；③ 介绍参与方式并邀约同行（范文中为 18 日周日十点中央公园、报名费 20 欧全额捐出，可跑 5/10 公里或当志愿者，还提议一起傍晚训练）。"},"t3-exhibition":{"cat":"邀请类","esTitle":"Invitar a una exposición de arte","zhExplain":"情境：邀请好友看本地画家的当代艺术展。要点：① 介绍展览内容与展期；② 约定时间地点；③ 提议看展后喝咖啡交流（范文中为 Antonio López 主题展展至月底、周六下午五点文化中心门口碰头且门票免费，学画的朋友看后力荐）。"},"t3-new-home":{"cat":"邀请类","esTitle":"Invitar a un amigo a casa","zhExplain":"情境：您搬了新家，打电话邀请朋友来。要点：① 问候并说搬家的事；② 描述新家如何并邀请他来；③ 约日期时间、告诉他怎么走（范文中五居室+健身房、Datun 路 53 号 401、地铁 15 号线）。","q":"Usted se ha mudado a un piso nuevo. Ahora llama a su amigo. Usted tiene que:\n1. Saludar y decirle de la mudanza;\n2. Describir cómo es su nuevo piso e invitarle a su piso;\n3. Quedar una fecha y hora, decirle cómo llegar a su piso.","model":"Buenas tardes, soy Gonzalo. Te llamo por teléfono para invitarte a mi casa. Me mudé a mi nuevo piso la semana pasada y estoy muy emocionado, considerándolo como una recompensa por mi arduo trabajo. El lugar es espacioso, con cinco habitaciones, una cocina y una amplia sala de estar. Lo que más me alegra es que puedo usar una de las habitaciones como gimnasio. Me encantaría que vinieras a celebrar conmigo y te prepararé una cena deliciosa. ¿Podríamos acordar un viernes de esta semana a las 8 de la noche? Mi piso está en la habitación 401, en la calle Datun No. 53. Puedes tomar la línea 15 del metro directamente a la entrada de la comunidad. Esperamos tu llegada. ¡Chao!"},"t3-weekend-plan":{"cat":"邀请类","esTitle":"Pensar en un plan para el fin de semana","zhExplain":"情境：和朋友商量下周末一起做什么。要点：① 问候并说起您的计划；② 说明您想做什么、为什么；③ 约定具体日期和时间（范文中下周生日去海边：排球、野餐、现场音乐）。","q":"Usted habla con un amigo de un plan que pueden hacer los dos juntos el próximo fin de semana. Usted tiene que:\n1. Saludar y hablar de su plan;\n2. Decir qué prefiere hacer y por qué.\n3. Quedar para un día y una hora.","model":"Buenas tardes, soy Gonzalo. Te llamo por teléfono para invitarte a viajar. La próxima semana es mi cumpleaños y mis padres me dieron algo de dinero para disfrutar de la naturaleza fuera de la ciudad. Quería invitarte a venir conmigo. Tenía en mente ir a la playa, donde podremos jugar vóley, hacer un picnic y disfrutar de música en vivo por la noche. Estoy planeando salir el próximo sábado a las 8 de la noche. Llámame si tienes alguna duda o si no puedes hacerlo. ¡Qué tengas un buen día! Chao."},"t3-cita":{"cat":"更改与取消类","esTitle":"Cancelar la cita","zhExplain":"情境：母亲意外摔伤住院，您无法赴与医生的预约，致电诊所改期。要点：① 问候并自报身份；② 说明发生了什么、为何去不了；③ 提议新的日期时间（范文中为改到下周三晚八点）。","q":"Usted no puede ir a la cita que ha quedado con el médico. Le llama y tiene que:\n1. Saludar y presentarse.\n2. Decir qué pasó y por qué no puede ir.\n3. Proponer otra fecha y hora.","model":"Buenas tardes, soy Gonzalo. ¿Cómo estás? Te llamo para cambiar la fecha de la cita que teníamos programada. Esta mañana recibí una llamada de mi madre; se cayó por las escaleras y la situación es bastante grave, así que ahora estoy en el hospital con ella. No estoy seguro de poder regresar a casa a tiempo para la cita. Lo siento, pero me gustaría proponerte cambiarla para las 8 de la noche del miércoles que viene. Si puedes, llámame por favor. Aprecio mucho tu comprensión. ¡Que tengas un buen día! ¡Chao!"},"t3-vuelo":{"cat":"更改与取消类","esTitle":"Cambiar las fechas de un boleto de avión","zhExplain":"情境：公司安排新项目，三个月后的旅行要推迟，致电航空公司改签。要点：① 问候并说明所购航班；② 解释改期原因并给出期望日期；③ 说明为何不应支付改签费（范文中为改到四个月后七月的第一个周末）。","q":"Usted ha comprado un boleto de avión para viajar dentro de 3 meses, pero ahora necesita cambiar la fecha del viaje, por lo que habla con un responsable de la compañía aérea. Usted tiene que:\n1. Saludar e informar del vuelo que ha comprado;\n2. Pedir el cambio de fechas para su vuelo y explicar por qué;\n3. Decir por qué cree que no debe pagar por el cambio.","model":"Buenas tardes, señor, mi nombre es Gonzalo. Te llamo para solicitar un cambio en la fecha de mi boleto de avión. Recientemente, mi jefe me informó que tendré que llevar a cabo un nuevo proyecto en los próximos meses. Por lo tanto, necesito posponer mis vacaciones para completar mi trabajo. ¿Existen otras opciones de horario disponibles? Si es posible, me gustaría cambiar la fecha para cuatro meses después, específicamente el primer fin de semana de julio. Eso es todo, agradezco mucho tu tiempo. ¡Que tengas un buen día! Chao."},"t3-trabajo":{"cat":"更改与取消类","esTitle":"Cambiar o cancelar una cita","zhExplain":"情境：儿子突然身体不适要提前接走，下午五点的预约去不了，致电改期。要点：① 自报姓名并说明预约信息；② 致歉并解释原因；③ 提议新的时间（范文中为改到下周五上午九点半，请对方来电确认）。"},"t3-enfermo":{"cat":"更改与取消类","esTitle":"Interesarse por un amigo enfermo","zhExplain":"情境：约好的朋友因流感爽约，您去问候他。要点：① 问候并关心病情；② 告诉他怎么休养能好得快；③ 表达祝愿并另约见面日期（范文中：多喝水、保暖、避风，改到下周六下午）。","q":"Usted había quedado con un amigo que no ha podido ir a la cita porque tiene gripe. Usted va a hablar con su amigo y tiene que:\n1. Saludar y preguntarle por su salud;\n2. Decirle qué puede hacer para mejorarse;\n3. Expresarle buenos deseos y proponer una nueva fecha para verse.","model":"Buenas tardes, soy Gonzalo. ¿Cómo estás? Ayer escuché a Enzo decir que estás enfermo, ¿es algo grave? Me siento apenado y triste por eso. Los resfriados son una enfermedad muy común; es necesario beber mucha agua, abrigarse más y tener cuidado de no exponerse al viento, ya que eso puede empeorar la situación. Además, quiero proponerte posponer nuestra cita programada para mañana por la tarde. Lo más importante ahora es que te recuperes rápidamente y tomes el tiempo necesario para descansar en casa. Si puedes, me gustaría posponer la fecha hasta el próximo sábado por la tarde. Te deseo una pronta recuperación. ¡Chao!"},"t3-retraso":{"cat":"更改与取消类","esTitle":"Avisar de que llegará tarde a casa","zhExplain":"情境：老板临时派了新项目必须今夜完成，打电话告知伴侣会晚归。要点：① 说明大约几点能到家；② 解释工作从何而来；③ 提出晚餐的解决办法（范文中为十点前回不去、食材已下单送到家，请对方照网上菜谱做）。"},"t3-hotel-change":{"cat":"更改与取消类","esTitle":"Solucionar un problema con una reservación","zhExplain":"情境：您订了度假酒店但没能按期到达，致电前台处理预订。要点：① 自报身份并解释为什么没到；② 提出新的入住日期；③ 询问这些日期有没有空房（范文中因新项目推迟到七月第一个周末）。","q":"Usted tenía una reservación para pasar sus vacaciones en un hotel, pero no pudo llegar. Usted tiene que:\n1. Identificarse y explicar por qué no pudo llegar;\n2. Proponer nuevas fechas para la reservación;\n3. Preguntar sobre la disponibilidad de esas fechas.","model":"Buenas tardes, señor, soy Gonzalo. Te llamo para solicitar la posposición de la fecha de la reservación. Recientemente, recibí una llamada de mi jefe informándome que necesitaré llevar a cabo un nuevo proyecto el próximo mes. Por lo tanto, debo posponer mis vacaciones para poder completar mi trabajo. ¿Existen otras opciones de horario disponibles? Si es posible, me gustaría reservar para el primer fin de semana de julio del próximo mes. Eso es todo. Aprecio mucho tu tiempo. ¡Que tengas un buen día!"},"t3-cancel-party":{"cat":"更改与取消类","esTitle":"Cancelar una fiesta planificada","zhExplain":"情境：聚会在即却确诊急性肠胃炎，只能致电朋友们取消。要点：① 说明病情与医嘱；② 致歉并体谅大家已做的安排；③ 提议改期（范文中为医嘱静养五天防传染、已把餐厅改到下月 24 日周六，之后逐一电话重排）。"},"t3-cancel-interview":{"cat":"更改与取消类","esTitle":"Cancelar una entrevista de trabajo","zhExplain":"情境：已接受另一家公司更匹配的录用，致电取消周五的营销岗面试。要点：① 自报身份并说明面试信息；② 诚恳致歉并解释原因；③ 感谢机会并盼保持联系（范文中为感谢对方审阅简历、祝其早日找到理想人选）。"},"t3-airport-cancel":{"cat":"更改与取消类","esTitle":"Cancelar la recogida en el aeropuerto","zhExplain":"情境：临时被召集参加紧急会议，无法按约去机场接朋友。要点：① 致歉并重述约定；② 说明原因、强调会议不能缺席；③ 给出替代方案（范文中为请有车且明天有空弟弟 Luis 接机，或朋友打车、您报销车费）。"},"t3-party-cook":{"cat":"更改与取消类","esTitle":"No poder llevar comida a la fiesta","zhExplain":"情境：您组织的聚会约定每人带一道菜，但您做不了了，要跟大家打招呼。要点：① 问候并说明情况；② 解释为什么带不了菜；③ 提出替代方案（范文中改为带酒水饮料）。注：PDF 此题目录标题印为「Cambiar cita」，实际内容为聚会带菜问题，以题目正文为准。","q":"Usted ha organizado una fiesta. Cada persona tiene que traer comida, pero usted no puede. Tiene que hablar con los demás:\n1. Saludar y hablar con sus amigos.\n2. Explicar por qué no puede llevar comida.\n3. Proponer alternativas sobre la comida.","model":"Buenas tardes, soy Gonzalo. ¿Cómo estás? Te llamo por teléfono para pedirte disculpas. Esta mañana recibí una llamada de mi madre; lamentablemente, ha tenido una reacción alérgica al pelo de animal y está bastante enferma. En este momento, estoy en el hospital con ella y no estoy seguro de poder regresar a tiempo para la fiesta. Por eso, no tendré tiempo suficiente para preparar el pastel que acordamos. Lamento la situación y espero que puedas entender. En su lugar, me gustaría llevar algunos vinos y bebidas a la fiesta. Si necesitas algo más, por favor, llámame. Agradezco tu comprensión. ¡Que tengas un buen día! Chao."},"t3-cancel-restaurant":{"cat":"更改与取消类","esTitle":"Cancelar una reserva de restaurante","zhExplain":"情境：岳母突然住院，周五的餐厅订位只能取消。要点：① 说明预订的姓名时间人数；② 致歉并解释突发情况；③ 询问能否改期（范文中为 El Olivo 餐厅九点半四人桌、想改到下周五同时段并留电话等确认）。"},"t3-cancel-work-meeting":{"cat":"更改与取消类","esTitle":"Cancelar una reunión de trabajo","zhExplain":"情境：母亲突发疾病住院，您无法参加工作例会。要点：① 致歉；② 解释不能到会的原因；③ 提出新的安排（范文中为母亲对动物毛发过敏住院，提议周三在岗到晚八点补上）。","q":"Usted tiene una reunión de trabajo y no puede ir. Tiene que:\n1. Disculparse.\n2. Explicar las razones por las que no puede ir a la reunión.\n3. Proponer una fecha y hora nuevas para la reunión.","model":"Buenas tardes, soy Gonzalo. ¿Cómo estás? Te llamo para solicitar un permiso. Esta mañana recibí una llamada de mi madre; ha tenido una reacción alérgica al pelo de los animales y está bastante enferma, así que ahora estoy en el hospital con ella. No estoy seguro de poder regresar puntualmente a la empresa. Lo siento, pero me gustaría solicitar quedarme hasta las 8 de la noche el miércoles que viene. Si puedes, llámame por favor. Aprecio mucho tu comprensión. ¡Que tengas un buen día! ¡Chao!"},"t3-change-swimming":{"cat":"更改与取消类","esTitle":"Cambiar el horario de curso","zhExplain":"情境：学校下周起晚间加开数学课，与游泳课时间冲突，致电改期。要点：① 问候并说明正在上的课程；② 解释要改日期时间的原因；③ 询问其他时段与价格（范文中为询问有没有别的时段可选、课程费用是否会变）。","q":"Usted está haciendo un curso de natación, pero necesita cambiar el día y la hora porque tiene un problema. Usted tiene que:\n1. Saludar e informar sobre el curso de natación que está haciendo.\n2. Explicar por qué necesita cambiar el día y la hora.\n3. Preguntar si hay otras opciones de horario y si hay cambios en el precio del curso.","model":"Buenas tardes, soy Gonzalo. ¿Cómo estás? Te llamo para comentarte que necesito cambiar la fecha de las clases de natación. Esta mañana recibí una llamada de mi escuela informándome que, a partir de la próxima semana, tendremos una clase adicional de matemáticas por la noche. Esto entra en conflicto con mi horario actual de clases de natación. ¿Existen otras opciones de horario disponibles y hay algún cambio en el precio del curso? Por favor, llámame cuando puedas. Agradezco mucho tu tiempo. ¡Que tengas un buen día! ¡Chao!"},"t3-cancel-friend":{"cat":"更改与取消类","esTitle":"Cancelar una cita con un amigo","zhExplain":"情境：与发小约好的见面去不了，打电话取消。要点：① 致歉；② 解释去不了的原因；③ 再约一次见面（范文中为母亲从楼梯摔下伤情较重正在陪护，提议改到下周三晚八点）。","q":"Usted ha quedado con un amigo de la infancia y no puede ir. Tiene que:\n1. Disculparse.\n2. Explicar las razones por las que no puede ir.\n3. Proponer otro encuentro.","model":"Buenas tardes, soy Gonzalo. ¿Cómo estás? Te llamo por teléfono para comunicarte que necesito posponer la cita que teníamos. Esta mañana recibí una llamada de mi madre; lamentablemente, sufrió una caída por las escaleras y la situación es bastante grave. En este momento, estoy en el hospital con ella y no estoy seguro de poder regresar a casa a tiempo para la cita. Lo siento mucho por cualquier inconveniente. Propongo que pospongamos nuestra reunión para las 8 de la noche del miércoles que viene. Si puedes, por favor, llámame para confirmar. Agradezco mucho tu comprensión. ¡Que tengas un buen día! Chao."},"t3-airport-late":{"cat":"更改与取消类","esTitle":"Avisar de un retraso en la recogida","zhExplain":"情境：高速公路发生事故大堵车，去机场接朋友会迟到，提前致电。要点：① 说明会晚到多久；② 解释堵车原因；③ 给出等待或打车两个选项（范文中为原定四点到、估计五点到，可让对方直接打车回您家、您报销）。"},"t3-rechazo":{"cat":"拒绝与道歉类","esTitle":"Rechazar una invitación y proponer otro día","zhExplain":"情境：朋友约您周六逛街，但您要陪父亲看病只能婉拒。要点：① 先谢邀请再说明原因；② 表达歉意；③ 提议另约一天（范文中为下周有两门考试，提议周二下午五点地铁口碰头、顺便喝咖啡叙旧）。"},"t3-reject-offer":{"cat":"拒绝与道歉类","esTitle":"Rechazar una oferta de trabajo","zhExplain":"情境：被公司录用却因生病无法按约定到岗，致电致歉并协商。要点：① 致歉；② 说明医生要求静养；③ 提出替代合作方式（范文中为建议改为线上进行以保住这次合作，并感谢理解）。","q":"Una empresa donde usted ha realizado una entrevista de trabajo le ha seleccionado. Sin embargo, usted no desea aceptarlo. Tiene que:\n1. Disculparse.\n2. Explicar las razones por las que no va a aceptar la oferta.\n3. Proponer diferentes opciones de colaboración.","model":"Buenas tardes, soy Gonzalo. ¿Qué tal? Te llamo por teléfono para disculparme por no poder asistir a la entrevista. Recientemente, he estado enfermo y el médico me ha recomendado descansar en la cama, lo que me impide acudir a nuestra entrevista programada. Sin embargo, estoy realmente interesado en trabajar contigo y, si es posible, me gustaría llevar a cabo la entrevista de forma virtual para facilitar nuestra cooperación. Agradezco tu comprensión y espero tu respuesta. ¡Que tengas un buen día! Chao."},"t3-decline-dog":{"cat":"拒绝与道歉类","esTitle":"Rechazar una petición de un amigo","zhExplain":"情境：朋友请您帮忙遛狗，您不得不拒绝。要点：① 表明很想帮忙但帮不了；② 说明家人对动物毛发过敏、近期备考；③ 推荐其他帮手（范文中为表妹一家爱狗且自己也养狗，您先去问、有答复立刻转告）。"},"t3-cine":{"cat":"拒绝与道歉类","esTitle":"Rechazar una invitación","zhExplain":"情境：朋友邀您一起看电影，但您不想看这部，要拒绝他。要点：① 问候并说明您已经看过；② 说说您对这部片的看法；③ 推荐另一部并道别（范文中推荐悬疑片并另约周三下午三点）。","q":"Su amigo le invita a ver una película juntos, pero usted no quiere. Le tiene que:\n1. Saludar y decirle qué ya ha visto.\n2. Decirle su opinión de esta película.\n3. Recomendarle otra y despedirse.","model":"Buenas tardes, soy Gonzalo. ¿Qué tal? Te llamo por teléfono para cambiar los planes que habíamos acordado. Sabes, como mis mejores amigos, me encantaría ir al cine contigo, pero la verdad es que vi esta película la semana pasada y la encontré bastante aburrida. Casualmente, Oscar me dijo hace dos días que había visto una película de suspenso y pensaba que era la mejor del año. ¿Qué opinas? Si es posible, me gustaría organizar una cita para el miércoles de esta semana a las tres de la tarde. Te esperaré en el lugar de siempre. ¡Que tengas un buen día! Chao."},"t3-decline-shopping":{"cat":"拒绝与道歉类","esTitle":"Rechazar una invitación de compras","zhExplain":"情境：父亲下午一点要看医生、您陪同，朋友的逛街邀约去不了。要点：① 说明原因并强调就诊时间难料；② 致歉；③ 另约时间地点（范文中为提议周二去对方公司旁边的商场，让对方少跑路）。"},"t3-apologize-contact":{"cat":"拒绝与道歉类","esTitle":"Pedir perdón por no contactar","zhExplain":"情境：三个月未联系好友，打电话道歉修复关系。要点：① 坦承失联并致歉；② 解释这段时间接连的变故；③ 约见面叙旧（范文中为换了岗位、照顾生病的父亲、手机坏了丢了通讯录，提议周五下午喝咖啡、由您做东）。"},"t3-decline-wedding":{"cat":"拒绝与道歉类","esTitle":"Disculparse por no asistir a una boda","zhExplain":"情境：最好的朋友结婚，但同期有必须参加的国际会议，无法出席。要点：① 先送上祝福；② 说明原因并表达遗憾；③ 提出补偿方式（范文中为找老板调期未果，婚后单独请她吃饭庆祝，并邮寄特别礼物补偿）。"},"t3-fight-apologize":{"cat":"拒绝与道歉类","esTitle":"Pedir perdón tras una discusión","zhExplain":"情境：三个月前与好友争吵后一直没联系，打电话求和。要点：① 承认自己当时说话过分；② 真诚道歉并反省；③ 约见面当面和好（范文中为承认自私说了伤人的话，提议周六喝咖啡，承诺今后多倾听少评判）。"},"t3-refuse-lend-book":{"cat":"拒绝与道歉类","esTitle":"Prestar libro","zhExplain":"情境：朋友想借您的书并承诺很快归还，您要拒绝。要点：① 问候并婉拒；② 解释为什么现在不能借给他；③ 建议一个替代办法（范文中下周有期末考要用书，改约一起讨论习题）。","q":"Un amigo le pide a usted que le preste un libro y le promete devolvérselo pronto. Usted tiene que:\n1. Saludar y negarse amablemente.\n2. Explicar las razones por las que no puede prestar el libro;\n3. Sugerir una alternativa.","model":"Buenas tardes, soy Gonzalo. ¿Cómo estás? Te llamo para responder a tu mensaje de esta mañana. Sabes que eres mi mejor amigo, pero este libro que quieres prestarme es importante para mí también esta semana. Dado que la próxima semana tengo el examen final de esta asignatura, ya necesito usarlo para repasar los conocimientos. Lo siento mucho. Si tienes dudas sobre este libro o esta asignatura, puedo quedar contigo a las 8 de la noche del miércoles para discutirlas. ¿Qué te parece? Llámame por favor. ¡Que tengas un buen día! ¡Chao!"},"t3-maleta":{"cat":"投诉与报告类","esTitle":"Informar de una maleta perdida","zhExplain":"情境：航班落地后托运行李没到，向航空公司报告求助。要点：① 说明航班号与行李外观特征；② 列明箱内重要物品；③ 要求尽快找回并给出方案（范文中为 276 航班红色中箱系蓝色缎带、内有关键文件和次日开会衣物，要求送酒店或提供应急行李箱）。"},"t3-lost-luggage":{"cat":"投诉与报告类","esTitle":"Reclamar una maleta perdida","zhExplain":"情境：行李没到目的地机场，您与旅客服务处交涉。要点：① 问候并说明所乘航班；② 说明箱内物品及为何急需；③ 要求经济援助（范文中航班 MC333、红色熊图案行李箱，请求垫付食宿费用）。","q":"Usted realizó un viaje en avión, pero su maleta no llegó al aeropuerto de destino. Usted habla con atención al viajero y tiene que:\n1. Saludar e indicar el vuelo en el que ha viajado;\n2. Explicar qué llevaba en su maleta y por qué lo necesita;\n3. Pedir una ayuda económica.","model":"Buenas tardes, mi nombre es Gonzalo. Te llamo para pedir ayuda. Fui pasajero en el vuelo MC333 ayer por la tarde y llegué a Madrid esta tarde, pero ahora no puedo encontrar mi maleta. Es una caja roja con un motivo de oso y contiene principalmente mi ropa y bolso. Tengo prisa en este momento porque tanto el alojamiento como las comidas cuestan dinero. ¿Podrían ayudarme a encontrar mi equipaje? Además, agradecería mucho si pudieran prestarme un poco de dinero. Gracias por su atención. Hasta luego."},"t3-cartera":{"cat":"投诉与报告类","esTitle":"Buscar objetos perdidos","zhExplain":"情境：钱包丢在商场，您去失物招领处报失。要点：① 问候并说明遭遇；② 描述钱包样子与里面装的东西；③ 讲最后一次使用的时间、当时在做什么、估计丢在哪里（范文中黑色钱包、约 400 欧、三张银行卡、二楼咖啡厅）。","q":"Usted ha perdido su cartera en un centro comercial y va a la oficina de objetos perdidos. Usted tiene que:\n1. Saludar y decir qué le ha pasado;\n2. Describir cómo era la cartera y qué llevaba en ella;\n3. Contar cuándo fue la última vez que la usó, qué estaba haciendo y dónde cree que la perdió.","model":"Buenas tardes, soy Gonzalo. Me gustaría solicitar su ayuda, ya que perdí mi billetera en su tienda esta mañana. Era de color negro y contenía aproximadamente 400 euros en efectivo, tres tarjetas bancarias y dos fotos de mi novia. Recuerdo que la última vez que la usé fue en la cafetería del segundo piso del centro comercial, y al llegar a casa, no la encontré. Espero que puedan ayudarme a localizarla. Si hay alguna novedad, por favor, llámenme para informarme. Agradezco mucho su ayuda. ¡Que tengan un buen día! Chao."},"t3-credit-card":{"cat":"投诉与报告类","esTitle":"Solucionar un problema con la tarjeta de crédito","zhExplain":"情境：信用卡被错误扣了一笔没买过的商品费用，您到银行处理。要点：① 自报身份并说明问题；② 要求退款；③ 询问退款的时间和方式（范文中请银行电话确认退款日期与形式）。","q":"Usted va al banco porque le hicieron un cobro en su tarjeta de crédito de un artículo que no compró. Tiene que:\n1. Identificarse y explicar cuál es su problema.\n2. Solicitar la devolución de su dinero.\n3. Pedir información sobre cuándo y cómo le devolverán el dinero.","model":"Buenas tardes, señor, mi nombre es Gonzalo. He venido al banco para informar un problema. Resulta que en su banco me han realizado un cargo en mi tarjeta de crédito por un artículo que no compré, y no tengo idea de qué se trata. No sé si es un error de su parte, pero necesito solicitar la devolución de mi dinero. Si hay alguna respuesta, por favor, llámeme por teléfono para confirmar la fecha y la forma de la devolución. Agradezco mucho su atención. Hasta luego."},"t3-flight-delay":{"cat":"投诉与报告类","esTitle":"Reclamar por un vuelo retrasado","zhExplain":"情境：原定 14:30 的航班延误超过三小时，到柜台交涉索赔。要点：① 说明航班与延误情况；② 要求解释原因与预计起飞时间；③ 依规索要餐饮补偿与经济赔偿（范文中为 IB-3402 航班，按欧盟条例逐条要求免费餐食、住宿交通与正式补偿）。"},"t3-credit-card-issue":{"cat":"投诉与报告类","esTitle":"Informar de un problema con el equipaje","zhExplain":"情境：您此前投诉行李丢失，客服回电处理。要点：① 确认投诉信息并致歉；② 告知行李下落与送达时间；③ 给出补偿方案（范文中为行李已在 Barajas 机场找到、次日上午送到塞维利亚住处，另赔 200 欧代金券并报销必需品）。"},"t3-return-shoes":{"cat":"投诉与报告类","esTitle":"Devolver unas zapatos a la tienda","zhExplain":"情境：上周六买的黑色高跟鞋尺码偏小，致电商店换货。要点：① 说明购买信息与商品细节；② 强调未穿、吊牌齐全并有小票；③ 询问换货流程与库存（范文中为 38 码换 39 码、询问能否邮寄办理，并提出尺码发错不应由您承担费用）。"},"t3-concert-refund":{"cat":"投诉与报告类","esTitle":"Pedir la devolución de su dinero","zhExplain":"情境：您期待已久的偶像演唱会临场取消，致电主办方。要点：① 自报身份并说明情况；② 说明因演唱会取消您遇到的问题（路费、酒店、餐饮）；③ 要求退票款并说明希望的退款方式（范文中还提出额外补偿）。","q":"Usted iba a ir a un concierto de su cantante favorito, pero lo cancelaron de último momento. Habla a la empresa que lo organizó. Usted tiene que:\n1. Identificarse y explicar al empleado la situación;\n2. Decir los problemas que tuvo porque cancelaron el concierto;\n3. Solicitar la devolución de su dinero y decir cómo quiere que la hagan.","model":"Buenas tardes, mi nombre es Gonzalo, un miembro de su concierto. Te llamo por teléfono para preguntarte por qué el concierto fue cancelado repentinamente. Vine desde lejos para ver el concierto, y los costos del hotel, la comida y el transporte no fueron gastos pequeños para mí. Si invertí todo esto por mi amor a su música, pensé que valdría la pena. Sin embargo, la cancelación del concierto me enojó como fan. Necesito solicitar un reembolso a su empresa y considerar una compensación adicional. Por favor, llámame, estoy esperando tu respuesta. ¡Que tengas un buen día! Chao."},"t3-library-lost":{"cat":"投诉与报告类","esTitle":"Informar de libros perdidos en la biblioteca","zhExplain":"情境：把图书馆借的两本书弄丢了，主动致电说明。要点：① 自报借书证号并说明书目；② 解释寻找经过与可能遗失的地点；③ 提出赔偿方案（范文中为《百年孤独》和《艺术的故事》、疑似落在火车上，愿意付罚款并询问按书价还是同版新购）。"},"t3-laundry-lost":{"cat":"投诉与报告类","esTitle":"Informar de prendas perdidas en la lavandería","zhExplain":"情境：取衣时发现少了两件上班要穿的衣服，致电洗衣店。要点：① 说明送洗时间与凭据；② 描述缺失衣物的品牌颜色尺码；③ 要求查找或按政策赔偿（范文中为深蓝真丝上衣（Zara，M）和米色亚麻裤（Mango，38），另发照片细节，希望本周内解决）。"},"t3-internet-complaint":{"cat":"投诉与报告类","esTitle":"Quejarse a la compañía de Internet","zhExplain":"情境：一周来网速远低于套餐标准，致电网络公司投诉。要点：① 陈述问题与持续时间；② 要求解释原因；③ 提出赔偿诉求（范文中为强调已影响居家办公效率和正常生活，要求有效解决并给予补偿）。","q":"Su conexión de internet se ha vuelto muy lenta. Llama a la compañía telefónica para quejarse. Tiene que:\n1. Exponer su problema;\n2. Pedir explicaciones;\n3. Reclamar una compensación.","model":"Buenas tardes, mi nombre es Gonzalo. Llamo para expresar mi preocupación sobre las bajas velocidades de Internet que he experimentado recientemente. Aunque tengo contratado un servicio de Internet rápido en su empresa, la velocidad ha sido notablemente lenta en la última semana. Esto ha afectado significativamente mi productividad en el trabajo y mi calidad de vida. Por lo tanto, espero que su empresa pueda proporcionar una solución efectiva y considerar alguna compensación. Quedo a la espera de su respuesta. Chao."},"t3-cancelled-flight":{"cat":"投诉与报告类","esTitle":"Reclamar a la aerolínea","zhExplain":"情境：航班被取消无法登机，您与航空公司工作人员交涉。要点：① 问候并自我介绍；② 说明情况；③ 询问解决方案（范文中说明次日中午须到马德里出差，要求改签当晚或次日凌晨航班）。","q":"Usted no puede tomar un vuelo debido a que fue cancelado. Usted habla con un empleado de la aerolínea y tiene que:\n1. Saludar y presentarse;\n2. Explicar la situación;\n3. Pedir información sobre la solución.","model":"Buenas tardes, mi nombre es Gonzalo, soy un miembro de su empresa. Llamo para preguntar por qué mi vuelo fue cancelado repentinamente esta noche. Necesito resaltar que tengo que llegar a Madrid mañana al mediodía por motivos de negocios, y llegar tarde tendrá un gran impacto en mi trabajo. ¿Hay otros vuelos a Madrid esta noche? ¿O existe alguna otra solución? Espero al menos poder abordar un vuelo mañana por la madrugada. Agradezco de antemano su respuesta y atención. Chao."},"t3-friend-no-show":{"cat":"投诉与报告类","esTitle":"Expresar enfado","zhExplain":"情境：朋友爽约没赴约，您打电话表达不满。要点：① 问候并问他发生了什么；② 表达您的恼火，说明为了赴约您没做成哪些事；③ 再另约一天（范文中改约下周六下午三点）。","q":"Usted ha quedado con un amigo que no ha ido a una cita que tenía con usted. Usted tiene que:\n1. Saludar y preguntar qué ha pasado;\n2. Expresar su enfado y decir qué cosas no pudo hacer por ir a la cita;\n3. Quedar para otro día.","model":"Buenas tardes, soy Gonzalo. ¿Qué tal? Te llamo por teléfono para preguntarte por qué no vas a la cita que hemos quedado. Sabes, estoy un poco molesto por eso, estaba emocionado por ir a cenar y al cine contigo. He preparado muchos bocadillos y bebidas, y si no vienes, la cita será menos divertida. Pero también puedo entender si tienes una agenda apretada. Podríamos cambiar la fecha para otro día que te convenga. Por ejemplo, el sábado que viene a las 3 de la tarde. ¿Qué te parece? Llámame, por favor. Espero tu respuesta. ¡Qué tengas un buen día! Chao."},"t3-turismo":{"cat":"建议与劝告类","esTitle":"Sugerir lugares para visitar","zhExplain":"情境：表妹要来您所在的城市游玩，想了解主要景点。要点：① 推荐可去的地方并说明位置；② 说说她可以做什么活动；③ 推荐吃饭的地方（范文中为博物馆、夜间演出、市中心拍照与老字号餐厅）。","q":"Una prima va a visitar la ciudad donde usted vive y quiere conocer los principales lugares que hay. Usted tiene que:\n1. Sugerir los lugares que puede visitar y decir en dónde están;\n2. Decir las actividades que puede realizar;\n3. Proponer lugares para comer.","model":"Buenas tardes, soy Gonzalo. Estoy muy feliz de saber que has venido a Beijing, porque pronto tendremos la oportunidad de vernos. Te llamo para recomendarte algunas atracciones turísticas en la ciudad. Beijing cuenta con muchos museos que son considerados lugares escénicos de cinco estrellas, representando un símbolo importante de la ciudad. Además, hay numerosas actuaciones nocturnas para disfrutar. El centro de la ciudad es también un lugar maravilloso para tomar fotos, con edificaciones que fusionan el estilo antiguo y moderno. Por último, quiero recomendarte el restaurante Wuming Ju, donde podrás degustar los sabores clásicos de Beijing. Espero tu respuesta. ¡Que tengas un buen día! ¡Chao!"},"t3-gimnasio":{"cat":"建议与劝告类","esTitle":"Explicar los beneficios del ejercicio","zhExplain":"情境：作为健身房教练，向会员讲解锻炼的好处并给出训练计划。要点：① 说明运动对身体的好处；② 强调对心理健康的独特作用；③ 给出循序渐进的建议（范文中为运动促进多巴胺分泌、缓解焦虑和压力，建议从每周两次温和运动起步养成习惯）。"},"t3-help-colleague":{"cat":"建议与劝告类","esTitle":"Ayudar a un compañero en su primer día de trabajo","zhExplain":"情境：新同事第一天上班，不熟悉公司各项设施与流程，您来帮忙。要点：① 自我介绍并告诉他办公地点；② 说明他的岗位职责；③ 主动提供帮助并约喝咖啡（范文中含 209 室、对外客户沟通与翻译工作）。","q":"Un compañero empieza a trabajar en su empresa y no conoce cómo funcionan algunos servicios. Usted tiene que hablar con él para:\n1. Identificarse y explicar a su compañero dónde va a trabajar;\n2. Explicar qué hará en su nuevo puesto;\n3. Ofrecer su ayuda e invitarlo a tomar un café.","model":"Buenas tardes, me llamo Gonzalo. Soy tu colega, así que permíteme darte un breve recorrido por tu trabajo. En primer lugar, tu oficina está en la habitación 209, en el segundo piso. Puedes encontrarla girando a la izquierda después de subir las escaleras. En segundo lugar, tu tarea principal es mantener la comunicación con los clientes extranjeros y traducir sus documentos. Si encuentras alguna dificultad, no dudes en venir y preguntarme; trataré de ayudarte a resolverlo. Si tienes tiempo después del trabajo hoy, podríamos ir a tomar un café juntos y puedes hacerme cualquier pregunta en ese momento. ¡Que tengas un buen día! ¡Chao!"},"t3-against-shopping":{"cat":"建议与劝告类","esTitle":"Expresar su opinión en contra de una compra por internet","zhExplain":"情境：伴侣想网购一样东西，您不同意，要劝说。要点：① 说明不同意及原因；② 解释为什么更喜欢在实体店买；③ 提出一起去逛街的日期和钟点（范文中：看不见质量、没法试穿、实体店价格相近，约周六下午两点）。","q":"Su pareja quiere comprar algo por internet. Usted debe:\n1. Decir que no está de acuerdo y por qué;\n2. Explicar por qué le gusta comprar en tiendas;\n3. Proponer un día y una hora para ir de compras.","model":"Buenas tardes, querida. Soy Gonzalo. Sé que estás interesada en comprar en línea, pero creo que hay muchas desventajas al hacerlo. Por ejemplo, en primer lugar, no conocemos la calidad de los productos porque no los hemos visto con nuestros propios ojos. En segundo lugar, si compramos ropa y zapatos, no podemos probárnoslos y no sabemos si serán adecuados para nosotros. Además, hay grandes centros comerciales cerca de nuestra casa y los precios son similares a los de la tienda en línea. ¿Por qué no vamos allí y compramos? Si compartes la misma opinión, podríamos acordar ir de compras juntos al centro comercial a las 2 de la tarde el sábado. Un beso."},"t3-university":{"cat":"申请与报名类","esTitle":"Solicitar el ingreso en la universidad","zhExplain":"情境：刚高中毕业，致电大学招生办完成入学申请。要点：① 说明意向专业；② 询问分数要求并确认材料收齐；③ 询问后续流程与录取通知时间（范文中为申请自笔译口译专业、已网上提交成绩单和证件，询问语言测试等补充手续）。"},"t3-cooking-class":{"cat":"申请与报名类","esTitle":"Inscribirse en un curso de cocina","zhExplain":"情境：看到广告后致电烹饪学校咨询报名。要点：① 询问课程类型与有无零基础班；② 询问上课时段与课程时长；③ 询问价格与付款方式（范文中为上午上班想报周末或晚间班、想分期付款，请对方把资料发到邮箱）。"},"t3-volunteer-elderly":{"cat":"申请与报名类","esTitle":"Ofrecerse como voluntario","zhExplain":"情境：看到招募启事，致电养老院报名做志愿者。要点：① 表达意愿与可服务的时间段；② 说明自身经验与技能；③ 询问具体工作内容与培训要求（范文中为照顾患阿尔茨海默病的祖母两年、会急救，可每周末上午服务，询问是否需要培训证书）。"},"t3-apply-scholarship":{"cat":"申请与报名类","esTitle":"Solicitar una beca","zhExplain":"情境：您想申请出国留学奖学金，到学校办公室办理。要点：① 自我介绍并说明从哪里得知奖学金信息；② 解释申请的原因；③ 说明想去哪里交换以及原因（PDF 原文如此；范文中西语专业、年级第三、三次国家级获奖，志在西语学习）。","q":"Usted quiere solicitar la beca para estudiar en el extranjero. Usted va a la oficina de su universidad y tiene que:\n1. Presentarse y decirle cómo le informó de la beca;\n2. Explicar las razones por las que quieren solicitar;\n3. Decir dónde quieren hacer el cambio y por qué.","model":"Buenas tardes, me llamo Gonzalo. Soy estudiante de tercer año en el Colegio de Lengua Extranjera y he visto varios tipos de becas publicadas en línea. He venido a la oficina para solicitar una beca para estudiar en el extranjero. Como estudiante de español, mi sueño siempre ha sido estudiar en España. He mantenido excelentes calificaciones y quedé en tercer lugar en mi grado, además de ganar tres premios nacionales. Si tengo la oportunidad de obtener la beca, me esforzaré aún más para llevar a cabo mi plan de estudiar en el extranjero y contribuir al desarrollo de la escuela y del país en el futuro. Agradezco mucho su tiempo."},"t3-apply-internship":{"cat":"申请与报名类","esTitle":"Solicitar hacer prácticas en una empresa","zhExplain":"情境：您想到一家公司实习，与公司负责人面谈。要点：① 问候、自我介绍并描述自己的特点；② 讲学业背景与实习/工作经历；③ 解释为什么想在这家公司实习（范文中西语大四、三段实习、独立接待外国客户并签单）。","q":"Usted quiere hacer prácticas en una empresa. Usted habla con el director de la empresa y tiene que:\n1. Saludar, identificarse y describir cómo es usted;\n2. Contar qué estudios tiene y hablar de su experiencia laboral;\n3. Explicar por qué le gustaría hacer prácticas en esa empresa.","model":"Buenas tardes, me llamo Gonzalo. Soy estudiante de cuarto año en el Colegio de Lengua Extranjera, con especialización en español. Durante mis años universitarios, realicé tres pasantías en instituciones educativas y empresas de comercio exterior. Especialmente en la última pasantía, gestioné de forma independiente la recepción y la comunicación con grupos de clientes extranjeros, firmando un pedido importante para la empresa. Creo que tengo excelentes habilidades para trabajar en equipo y una capacidad destacada para el manejo independiente. Al mismo tiempo, como sabemos, su empresa es líder en la industria comercial. Espero tener la oportunidad de acumular experiencia en su empresa y contribuir a su éxito. Agradezco mucho su recepción. ¡Gracias!"},"t3-sell-apartment":{"cat":"信息发布类","esTitle":"Vender su piso","zhExplain":"情境：您决定卖房，发布售房信息。要点：① 说明为什么现在需要用钱；② 介绍房子的优点与特点；③ 谈价格（范文中家人健康原因急售、120 平四居室、朝阳路近地铁、报价 50 万欧）。","q":"Usted ha decidido vender su piso. Tiene que:\n1. Indicar por qué necesita el dinero ahora;\n2. Explicar las características y cosas buenas que tiene su piso;\n3. Hablar sobre el precio del piso.","model":"Buenas tardes, soy Gonzalo. Debido a que mi familia enfrenta problemas de salud y necesito reunir una suma considerable de dinero, he decidido vender la casa lo antes posible. La vivienda cuenta con 120 metros cuadrados y consta de cuatro habitaciones, una sala de estar y una cocina. Está ubicada en el centro de la calle Chaoyang de la ciudad, cerca del metro y de la escuela. Además, hay grandes centros comerciales a menos de un kilómetro de distancia, lo cual la hace muy conveniente para la vida diaria, especialmente para que los niños vayan a la escuela o para ti al trabajar. El precio actual es de 500.000 euros. Si estás interesado en esta casa, por favor, llámame. Agradezco tu atención."},"t3-change-class":{"cat":"请求类","esTitle":"Pedir un cambio de clase","zhExplain":"情境：您想换班，与就读的西语学校（academia）校长面谈。要点：① 问候并自我介绍；② 解释为什么想换到另一时段的班级；③ 说明您什么时间可以上课。备考提示（PDF 原文注）：请假理由别用「从楼梯上摔下来」「庆祝爸妈婚礼纪念日」这类考官听腻的说法，准备一个不太 low 的理由，范文以母亲过敏住院为由。"},"t3-cancel-weekend":{"cat":"更改与取消类","esTitle":"Cancelar los planes de fin de semana","zhExplain":"情境：母亲摔伤住院，周末与朋友的聚会去不了，打电话说明。要点：① 问候并致歉；② 解释您必须做什么；③ 提议替代活动（范文中为提议推迟到下周、一起去市中心看悬疑电影）。"},"t3-wedding-call":{"cat":"邀请类","esTitle":"Organizar su boda","zhExplain":"情境：您要办婚礼，正在逐个通知宾客。要点：① 告知要办婚礼及缘由；② 说明婚礼地点、日期和钟点；③ 说明怎么到达、婚礼上会做什么。注：本条与「Invitar a una boda」范文几乎相同，PDF 原文如此，可作为同题复练。"}};
