window._sieleT45V91Apply=function(bank,tarea){
 try{
  if(!bank)return 0;
  var P=window.SIELE_T45_PASSAGE_V91||{},S=window.SIELE_T5_STANCE_V91||{},n=0;
  bank.forEach(function(q){
   var tp=q&&q.topic;if(!tp)return;
   if(tarea===4&&P[tp]&&P[tp].passage){q.passage=P[tp].passage;q.passageZh=P[tp].passageZh;q.passageSrc=P[tp].source;n++;}
   if(tarea===5&&S[tp]&&q.stances){['a','b'].forEach(function(k){if(S[tp][k]&&S[tp][k].statement&&q.stances[k]){q.stances[k].statement=S[tp][k].statement;n++;}});}
  });
  return n;
 }catch(e){console.warn('[v91] T45 passage apply 失败:',e);return 0;}
};
